V20_SCHEMA_STATEMENTS = (
    """CREATE TABLE IF NOT EXISTS library_bootstrap_receipts (
        database_uuid TEXT NOT NULL REFERENCES database_meta(database_uuid) ON DELETE RESTRICT,
        authenticated_principal TEXT NOT NULL
          CHECK(authenticated_principal='main_native_user_gesture'),
        command_type TEXT NOT NULL CHECK(command_type='library.bootstrap'),
        command_version TEXT NOT NULL CHECK(command_version='1'),
        request_id TEXT NOT NULL CHECK(
          length(request_id)=67 AND substr(request_id,1,3)='lb_' AND
          substr(request_id,4) NOT GLOB '*[^0-9a-f]*'),
        request_sha256 TEXT NOT NULL CHECK(
          length(request_sha256)=64 AND request_sha256 NOT GLOB '*[^0-9a-f]*'),
        intent_created_at_ms INTEGER NOT NULL CHECK(
          typeof(intent_created_at_ms)='integer' AND intent_created_at_ms>=0),
        intent_expires_at_ms INTEGER NOT NULL CHECK(
          typeof(intent_expires_at_ms)='integer' AND
          intent_expires_at_ms=intent_created_at_ms+300000),
        native_confirmed_at_ms INTEGER NOT NULL CHECK(
          typeof(native_confirmed_at_ms)='integer' AND
          native_confirmed_at_ms>=intent_created_at_ms AND
          native_confirmed_at_ms<intent_expires_at_ms),
        candidate_binding_sha256 TEXT NOT NULL CHECK(
          length(candidate_binding_sha256)=64 AND
          candidate_binding_sha256 NOT GLOB '*[^0-9a-f]*'),
        library_root_id TEXT NOT NULL REFERENCES library_roots(id) ON DELETE RESTRICT,
        library_root_fingerprint TEXT NOT NULL CHECK(
          length(library_root_fingerprint)=64 AND
          library_root_fingerprint NOT GLOB '*[^0-9a-f]*'),
        library_root_device INTEGER NOT NULL CHECK(
          typeof(library_root_device)='integer' AND library_root_device>=0),
        library_root_inode INTEGER NOT NULL CHECK(
          typeof(library_root_inode)='integer' AND library_root_inode>=0),
        project_id TEXT NOT NULL REFERENCES creative_projects(id) ON DELETE RESTRICT,
        brief_revision INTEGER NOT NULL CHECK(brief_revision=1),
        brief_content_sha256 TEXT NOT NULL CHECK(
          length(brief_content_sha256)=64 AND
          brief_content_sha256 NOT GLOB '*[^0-9a-f]*'),
        scan_job_id TEXT NOT NULL UNIQUE REFERENCES media_jobs(id) ON DELETE RESTRICT,
        blueprint_operation_id TEXT NOT NULL,
        blueprint_revision INTEGER NOT NULL CHECK(blueprint_revision=1),
        blueprint_content_sha256 TEXT NOT NULL CHECK(
          length(blueprint_content_sha256)=64 AND
          blueprint_content_sha256 NOT GLOB '*[^0-9a-f]*'),
        blueprint_semantic_sha256 TEXT NOT NULL CHECK(
          length(blueprint_semantic_sha256)=64 AND
          blueprint_semantic_sha256 NOT GLOB '*[^0-9a-f]*'),
        response_status INTEGER NOT NULL CHECK(response_status=201),
        response_json TEXT NOT NULL CHECK(length(response_json) BETWEEN 2 AND 1048576),
        response_sha256 TEXT NOT NULL CHECK(
          length(response_sha256)=64 AND response_sha256 NOT GLOB '*[^0-9a-f]*'),
        receipt_sha256 TEXT NOT NULL CHECK(
          length(receipt_sha256)=64 AND receipt_sha256 NOT GLOB '*[^0-9a-f]*'),
        created_at TEXT NOT NULL,
        PRIMARY KEY(database_uuid,authenticated_principal,command_type,
                    command_version,request_id),
        UNIQUE(project_id),
        FOREIGN KEY(project_id,brief_revision)
          REFERENCES creative_briefs(project_id,revision)
          ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
        FOREIGN KEY(project_id,blueprint_revision,blueprint_content_sha256,
                    blueprint_semantic_sha256,blueprint_operation_id)
          REFERENCES creative_blueprint_revisions(
                    project_id,revision,content_sha256,semantic_sha256,operation_id)
          ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
        FOREIGN KEY(project_id,blueprint_operation_id)
          REFERENCES blueprint_desktop_receipt_integrity(project_id,operation_id)
          ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED)""",
    """CREATE INDEX IF NOT EXISTS idx_library_bootstrap_receipts_root
       ON library_bootstrap_receipts(library_root_id,created_at)""",
    """CREATE INDEX IF NOT EXISTS idx_library_bootstrap_receipts_project
       ON library_bootstrap_receipts(project_id,created_at)""",
    """CREATE TRIGGER IF NOT EXISTS trg_library_bootstrap_receipts_complete
       BEFORE INSERT ON library_bootstrap_receipts
       WHEN NOT EXISTS (
              SELECT 1 FROM database_meta meta
               WHERE meta.singleton=1 AND meta.database_uuid=NEW.database_uuid) OR
            NOT EXISTS (
              SELECT 1 FROM library_roots root
               WHERE root.id=NEW.library_root_id
                 AND root.permission_fingerprint=NEW.library_root_fingerprint
                 AND root.status='active') OR
            NOT EXISTS (
              SELECT 1 FROM creative_projects project
               WHERE project.id=NEW.project_id AND project.status='active') OR
            NOT EXISTS (
              SELECT 1 FROM creative_briefs brief
               WHERE brief.project_id=NEW.project_id
                 AND brief.revision=NEW.brief_revision
                 AND brief.content_sha256=NEW.brief_content_sha256) OR
            NOT EXISTS (
              SELECT 1 FROM media_jobs job
               WHERE job.id=NEW.scan_job_id AND job.database_uuid=NEW.database_uuid
                 AND job.kind='library_scan' AND job.asset_id IS NULL
                 AND job.analysis_run_id IS NULL AND job.status='queued'
                 AND job.stage='awaiting_scan_worker' AND job.progress=0
                 AND job.attempt=1 AND job.cancel_requested=0
                 AND job.checkpoint_json='{}' AND job.error_json IS NULL
                 AND job.started_at IS NULL AND job.heartbeat_at IS NULL
                 AND job.finished_at IS NULL) OR
            NOT EXISTS (
              SELECT 1 FROM creative_blueprint_revisions revision
               JOIN creative_blueprint_heads head
                 ON head.project_id=revision.project_id
                AND head.revision=revision.revision
                AND head.content_sha256=revision.content_sha256
                AND head.semantic_sha256=revision.semantic_sha256
                AND head.operation_id=revision.operation_id
               WHERE revision.project_id=NEW.project_id
                 AND revision.revision=NEW.blueprint_revision
                 AND revision.content_sha256=NEW.blueprint_content_sha256
                 AND revision.semantic_sha256=NEW.blueprint_semantic_sha256
                 AND revision.operation_id=NEW.blueprint_operation_id
                 AND revision.authority_state='unverified') OR
            NOT EXISTS (
              SELECT 1 FROM creative_blueprint_operations operation
               WHERE operation.project_id=NEW.project_id
                 AND operation.id=NEW.blueprint_operation_id
                 AND operation.command_type='blueprint.commit_proposal'
                 AND operation.command_version='1'
                 AND operation.input_sha256=NEW.request_sha256
                 AND operation.result_kind='revision_created'
                 AND operation.result_revision=NEW.blueprint_revision
                 AND operation.result_content_sha256=NEW.blueprint_content_sha256) OR
            NOT EXISTS (
              SELECT 1 FROM blueprint_command_receipts receipt
               JOIN blueprint_desktop_receipt_integrity integrity
                 ON integrity.project_id=receipt.project_id
                AND integrity.operation_id=receipt.operation_id
               WHERE receipt.database_uuid=NEW.database_uuid
                 AND receipt.authenticated_principal='desktop_app'
                 AND receipt.project_id=NEW.project_id
                 AND receipt.command_type='blueprint.commit_proposal'
                 AND receipt.command_version='1'
                 AND receipt.idempotency_key='library-bootstrap:'||NEW.request_id
                 AND receipt.request_sha256=NEW.request_sha256
                 AND receipt.operation_id=NEW.blueprint_operation_id
                 AND receipt.response_status=201)
       BEGIN SELECT RAISE(ABORT,'library bootstrap receipt dependencies are incomplete'); END""",
    """CREATE TRIGGER IF NOT EXISTS trg_library_bootstrap_receipts_no_update
       BEFORE UPDATE ON library_bootstrap_receipts
       BEGIN SELECT RAISE(ABORT,'library_bootstrap_receipts are immutable'); END""",
    """CREATE TRIGGER IF NOT EXISTS trg_library_bootstrap_receipts_no_delete
       BEFORE DELETE ON library_bootstrap_receipts
       BEGIN SELECT RAISE(ABORT,'library_bootstrap_receipts are immutable'); END""",
    """CREATE TRIGGER IF NOT EXISTS trg_library_bootstrap_roots_identity_immutable
       BEFORE UPDATE ON library_roots
       WHEN EXISTS (
              SELECT 1 FROM library_bootstrap_receipts receipt
               WHERE receipt.library_root_id=OLD.id) AND
            (NEW.id IS NOT OLD.id OR
             NEW.canonical_path IS NOT OLD.canonical_path OR
             NEW.permission_fingerprint IS NOT OLD.permission_fingerprint OR
             NEW.created_at IS NOT OLD.created_at)
       BEGIN SELECT RAISE(ABORT,'library bootstrap root identity is immutable'); END""",
    """CREATE TRIGGER IF NOT EXISTS trg_library_bootstrap_jobs_identity_immutable
       BEFORE UPDATE ON media_jobs
       WHEN EXISTS (
              SELECT 1 FROM library_bootstrap_receipts receipt
               WHERE receipt.scan_job_id=OLD.id) AND
            (NEW.id IS NOT OLD.id OR NEW.database_uuid IS NOT OLD.database_uuid OR
             NEW.kind IS NOT OLD.kind OR NEW.asset_id IS NOT OLD.asset_id OR
             NEW.analysis_run_id IS NOT OLD.analysis_run_id OR
             NEW.created_at IS NOT OLD.created_at)
       BEGIN SELECT RAISE(ABORT,'library bootstrap scan identity is immutable'); END""",
    """CREATE TRIGGER IF NOT EXISTS trg_library_bootstrap_briefs_no_update
       BEFORE UPDATE ON creative_briefs
       WHEN EXISTS (
              SELECT 1 FROM library_bootstrap_receipts receipt
               WHERE receipt.project_id=OLD.project_id
                 AND receipt.brief_revision=OLD.revision)
       BEGIN SELECT RAISE(ABORT,'library bootstrap brief is immutable'); END""",
    """CREATE TRIGGER IF NOT EXISTS trg_library_bootstrap_briefs_no_delete
       BEFORE DELETE ON creative_briefs
       WHEN EXISTS (
              SELECT 1 FROM library_bootstrap_receipts receipt
               WHERE receipt.project_id=OLD.project_id
                 AND receipt.brief_revision=OLD.revision)
       BEGIN SELECT RAISE(ABORT,'library bootstrap brief is immutable'); END""",
)

