class BoundAssetSourceFile:
    """One exact imported source inode held open for a bounded read."""

    def __init__(
        self,
        *,
        root_path: Path,
        root_descriptor: int,
        relative_path: str,
        handle: BinaryIO,
        identity: tuple[int, int, int, int, int],
        asset: Mapping[str, object],
    ) -> None:
        self.root_path = root_path
        self.root_descriptor = root_descriptor
        self.relative_path = relative_path
        self.handle = handle
        self.identity = identity
        self.asset = MappingProxyType(dict(asset))
        self.size = identity[2]
        self._closed = False

    def verify_current_identity(self) -> None:
        if self._closed:
            raise ValueError("Bound asset source is closed.")
        if _source_file_identity(os.fstat(self.handle.fileno())) != self.identity:
            raise ValueError("Bound asset source inode changed while reading.")
        current_root = _open_absolute_directory_no_follow(self.root_path)
        try:
            if _directory_identity(os.fstat(current_root)) != _directory_identity(
                os.fstat(self.root_descriptor)
            ):
                raise ValueError("Bound asset source root changed while reading.")
        finally:
            os.close(current_root)
        current_file = MediaRepository._open_relative_regular(
            self.root_descriptor,
            self.relative_path,
        )
        try:
            if _source_file_identity(os.fstat(current_file)) != self.identity:
                raise ValueError("Bound asset source path changed while reading.")
        finally:
            os.close(current_file)

    def content_sha256(
        self,
        *,
        require_active: Callable[[], None] | None = None,
    ) -> str:
        if self._closed:
            raise ValueError("Bound asset source is closed.")
        original_offset = self.handle.tell()
        try:
            digest = hashlib.sha256()
            self.handle.seek(0)
            for chunk in iter(lambda: self.handle.read(1024 * 1024), b""):
                if require_active is not None:
                    require_active()
                digest.update(chunk)
            return digest.hexdigest()
        finally:
            self.handle.seek(original_offset)

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            self.handle.close()
        finally:
            os.close(self.root_descriptor)

    def __enter__(self) -> BoundAssetSourceFile:
        return self

    def __exit__(self, _exc_type, _exc, _traceback) -> None:
        self.close()


