@dataclass(frozen=True)
class _ValidatedBlueprintLedgerSnapshot:
    """Exact Blueprint ledger attestation valid only in its originating read transaction."""

    token: object
    connection: sqlite3.Connection
    project_id: str
    issuance_nonce: str
    transaction_epoch: int
    head_json: str
    revision_count: int
    operation_count: int
    operation_jsons: tuple[str, ...]
    validation_context: _BlueprintReadValidationContext
    seal_sha256: str

    @staticmethod
    def _decode_mapping(value: str) -> dict[str, object]:
        decoded = json.loads(value)
        if type(decoded) is not dict:
            raise BlueprintIntegrityError("blueprint_read_attestation_invalid")
        return decoded

    @property
    def head(self) -> dict[str, object]:
        return self._decode_mapping(self.head_json)

    @property
    def operations(self) -> tuple[dict[str, object], ...]:
        return tuple(self._decode_mapping(value) for value in self.operation_jsons)


class _MediaConnection(sqlite3.Connection):
    """Private connection subtype carrying repository-only transaction state."""

    def _install_blueprint_read_transaction_tracking(self) -> None:
        if getattr(self, "_blueprint_read_transaction_tracking", False):
            return
        self._blueprint_read_transaction_epoch = 0
        self._blueprint_read_attestation_registry: dict[str, object] = {}
        self._blueprint_user_trace_callback: Callable[[str], object] | None = None
        connection_ref = weakref.ref(self)

        def dispatch(statement: str) -> None:
            connection = connection_ref()
            if connection is None:
                return
            connection._observe_blueprint_transaction_statement(statement)
            callback = connection._blueprint_user_trace_callback
            if callback is not None:
                callback(statement)

        self._blueprint_internal_trace_callback = dispatch
        self._blueprint_read_transaction_tracking = True
        super().set_trace_callback(dispatch)

    def _advance_blueprint_read_transaction_epoch(self) -> None:
        self._blueprint_read_transaction_epoch = int(getattr(self, "_blueprint_read_transaction_epoch", 0)) + 1
        registry = getattr(self, "_blueprint_read_attestation_registry", None)
        if isinstance(registry, dict):
            registry.clear()

    def _observe_blueprint_transaction_statement(self, statement: str) -> None:
        remaining = statement.lstrip()
        while remaining:
            if remaining.startswith("--"):
                newline = remaining.find("\n")
                if newline < 0:
                    return
                remaining = remaining[newline + 1 :].lstrip()
                continue
            if remaining.startswith("/*"):
                end = remaining.find("*/", 2)
                if end < 0:
                    return
                remaining = remaining[end + 2 :].lstrip()
                continue
            break
        keyword = remaining.split(None, 1)[0].rstrip(";").upper() if remaining else ""
        if keyword in {
            "ALTER",
            "ANALYZE",
            "ATTACH",
            "BEGIN",
            "COMMIT",
            "CREATE",
            "DETACH",
            "DROP",
            "END",
            "PRAGMA",
            "REINDEX",
            "ROLLBACK",
            "SAVEPOINT",
            "RELEASE",
            "VACUUM",
        }:
            self._advance_blueprint_read_transaction_epoch()

    def set_trace_callback(
        self,
        trace_callback: Callable[[str], object] | None,
    ) -> None:
        if not getattr(self, "_blueprint_read_transaction_tracking", False):
            return super().set_trace_callback(trace_callback)
        self._blueprint_user_trace_callback = trace_callback
        return super().set_trace_callback(self._blueprint_internal_trace_callback)

    def _deny_blueprint_transaction_control(self) -> None:
        if getattr(self, "_blueprint_transaction_control_protected", False):
            raise BlueprintIntegrityError("blueprint_schema_mutation_forbidden")

    def commit(self) -> None:
        self._deny_blueprint_transaction_control()
        try:
            return super().commit()
        finally:
            self._advance_blueprint_read_transaction_epoch()

    def rollback(self) -> None:
        self._deny_blueprint_transaction_control()
        try:
            return super().rollback()
        finally:
            self._advance_blueprint_read_transaction_epoch()

    def close(self) -> None:
        if not getattr(self, "_blueprint_read_transaction_closed", False):
            self._advance_blueprint_read_transaction_epoch()
            self._blueprint_read_transaction_closed = True
            self._blueprint_user_trace_callback = None
            try:
                super().set_trace_callback(None)
            except sqlite3.ProgrammingError:
                pass
        return super().close()

    def executescript(self, sql_script: str, /) -> sqlite3.Cursor:
        self._deny_blueprint_transaction_control()
        return super().executescript(sql_script)

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc_value: BaseException | None,
        traceback: object,
    ) -> bool:
        self._deny_blueprint_transaction_control()
        return super().__exit__(exc_type, exc_value, traceback)


