def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def new_id(prefix: str) -> str:
    return f"{prefix}_{uuid.uuid4().hex}"


def canonical_json(value: object) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)


def library_bootstrap_candidate_binding_sha256(
    *,
    canonical_root: str | Path,
    database_path: str | Path,
    expected_library_root_device: int | str,
    expected_library_root_inode: int | str,
) -> str:
    """Hash the exact cross-language native Library binding envelope."""

    fields = {
        "canonical_root": str(canonical_root),
        "database_path": str(database_path),
        "expected_library_root_device": str(expected_library_root_device),
        "expected_library_root_inode": str(expected_library_root_inode),
    }
    material = (
        f"{_LIBRARY_BOOTSTRAP_BINDING_DOMAIN}\0".encode("ascii")
        + canonical_json(fields).encode("utf-8")
    )
    return hashlib.sha256(material).hexdigest()


def _json_container_depth_within_limit(raw: str, limit: int) -> bool:
    """Bound nesting before recursive stdlib decode/canonicalization.

    CPython's JSON recursion tolerance is an implementation detail and changed
    across supported runtimes.  This lexical pass ignores brackets inside JSON
    strings; malformed structure remains the decoder's responsibility.
    """

    depth = 0
    in_string = False
    escaped = False
    for character in raw:
        if in_string:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                in_string = False
            continue
        if character == '"':
            in_string = True
        elif character in "[{":
            depth += 1
            if depth > limit:
                return False
        elif character in "]}" and depth > 0:
            depth -= 1
    return True


def content_sha256(value: object) -> str:
    return hashlib.sha256(canonical_json(value).encode()).hexdigest()


def _canonical_json_sha256_without(raw: object, field: object) -> str | None:
    """SQLite trigger helper for self-authenticating canonical JSON documents."""

    if type(raw) is not str or type(field) is not str:
        return None
    try:
        value = json.loads(raw)
        if type(value) is not dict or field not in value:
            return None
        value.pop(field)
        return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()
    except (TypeError, ValueError, UnicodeError, RecursionError):
        return None


def _canonical_json_sha256(raw: object) -> str | None:
    """Hash one JSON value after canonical parsing and serialization."""

    if type(raw) is not str:
        return None
    try:
        value = json.loads(raw)
        return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()
    except (TypeError, ValueError, UnicodeError, RecursionError):
        return None


def _sqlite_blob_sha256(raw: object) -> str | None:
    if not isinstance(raw, bytes):
        return None
    return hashlib.sha256(raw).hexdigest()


def _validate_image_contract_document(raw: object, kind: object) -> int:
    """SQLite fail-closed bridge to the same closed Python contracts as writers."""

    if type(raw) is not str or type(kind) is not str:
        return 0
    validators = {
        "result": require_valid_image_analysis_result,
        "change": require_valid_projection_change,
        "publish_receipt": require_valid_publish_receipt,
        "projection_receipt": require_valid_projection_receipt,
        "manifest": require_valid_projection_manifest,
    }
    validator = validators.get(kind)
    if validator is None:
        return 0
    try:
        validator(json.loads(raw))
    except (ImageAnalysisContractError, TypeError, ValueError, json.JSONDecodeError):
        return 0
    return 1


def _validate_projected_image_row_document(raw: object) -> int:
    if type(raw) is not str:
        return 0
    try:
        require_valid_projected_image_index_row(json.loads(raw))
    except (ImageProjectionRenderError, TypeError, ValueError, json.JSONDecodeError):
        return 0
    return 1


def _validate_image_attempt_authority_document(raw: object) -> int:
    if type(raw) is not str:
        return 0
    try:
        require_valid_image_analysis_attempt_authority(json.loads(raw))
    except (ImageAnalysisJobContractError, TypeError, ValueError, json.JSONDecodeError):
        return 0
    return 1


def _loads(value: object, fallback: Any) -> Any:
    if not isinstance(value, str) or not value:
        return fallback
    try:
        return json.loads(value)
    except (TypeError, json.JSONDecodeError):
        return fallback


def _permission_fingerprint_from_stat(path: Path, stat_result: os.stat_result) -> str:
    material = f"{path}\0{stat_result.st_dev}\0{stat_result.st_ino}\0{stat_result.st_mode}"
    return hashlib.sha256(material.encode()).hexdigest()


def _permission_fingerprint(path: Path) -> str:
    return _permission_fingerprint_from_stat(path, path.stat())


def permission_fingerprint(path: Path) -> str:
    return _permission_fingerprint(path)


def _directory_identity(value: os.stat_result) -> tuple[int, int]:
    return int(value.st_dev), int(value.st_ino)


def _source_file_identity(value: os.stat_result) -> tuple[int, int, int, int, int]:
    return (
        int(value.st_dev),
        int(value.st_ino),
        int(value.st_size),
        int(value.st_mtime_ns),
        int(value.st_ctime_ns),
    )


def _open_absolute_directory_no_follow(path: Path) -> int:
    """Open every absolute directory component without following symlinks."""

    no_follow = getattr(os, "O_NOFOLLOW", None)
    directory = getattr(os, "O_DIRECTORY", None)
    if no_follow is None or directory is None:
        raise RuntimeError("Secure source opening is unavailable on this platform.")
    canonical = Path(os.path.abspath(path))
    if not canonical.is_absolute():  # pragma: no cover - abspath is absolute
        raise ValueError("Approved library root is invalid.")
    flags = os.O_RDONLY | no_follow | directory | getattr(os, "O_CLOEXEC", 0)
    descriptor = os.open(canonical.anchor, flags)
    try:
        for component in canonical.parts[1:]:
            next_descriptor = os.open(component, flags, dir_fd=descriptor)
            os.close(descriptor)
            descriptor = next_descriptor
        if not stat.S_ISDIR(os.fstat(descriptor).st_mode):
            raise ValueError("Approved library root is not a directory.")
        return descriptor
    except Exception:
        os.close(descriptor)
        raise


class MediaRepository(
    ProviderEgressPersistenceMixin,
    ImageAnalysisPersistenceMixin,
    LibraryScanPersistenceMixin,
):
    """Versioned additive media store. Each instance is permanently bound to one DB path."""

    _V20_SCHEMA_OBJECTS = _V20_SCHEMA_OBJECTS

    def __init__(self, db_path: Path):
        self.db_path = db_path.expanduser().resolve()
        # Keep app-managed output roots open for this repository lifetime.
        # Holding the original directory inode prevents Linux from immediately
        # reusing it after a remove-and-recreate at the same path, closing a
        # platform-specific identity gap that a persisted dev/inode fingerprint
        # alone cannot detect.
        self._output_root_descriptors: dict[str, int] = {}
        # Native export roots are prepared without touching SQLite.  The exact
        # descriptor is promoted only after an export command commits the root,
        # operation, job, and receipt in one transaction.
        self._prepared_export_roots: dict[str, tuple[Path, str, int]] = {}
        self._prepared_export_roots_lock = threading.Lock()
        self._artifact_cache: dict[str, tuple[int, int, int, int, int, str]] = {}
        self._artifact_cache_lock = threading.Lock()
        self._source_cache: dict[str, tuple[int, int, int, int, int, str]] = {}
        self._source_cache_lock = threading.Lock()
        # A running Library scan is additionally fenced by its durable attempt
        # number.  The process-local generation map prevents another runtime
        # generation in the same process from borrowing that attempt; after a
        # crash, typed recovery interrupts the old attempt before resume can
        # increment and claim the same durable job ID again.
        self._library_scan_runtime_leases: dict[tuple[str, int], str] = {}
        self._library_scan_runtime_leases_lock = threading.Lock()
        self._blueprint_runtime_pid = os.getpid()
        self._blueprint_anchor_lock = threading.RLock()
        self._blueprint_anchor: _MediaConnection | None = None
        self._blueprint_anchor_identity: tuple[int, int] | None = None
        self._blueprint_anchor_pid: int | None = None
        # Unlike an anchor identity, this binding survives cold fallback,
        # anchor discard, LRU eviction, and WAL data-version invalidation.  A
        # repository object may attest only one database inode for its entire
        # Blueprint lifetime.
        self._blueprint_bound_database_identity: tuple[int, int] | None = None
        self._blueprint_database_binding_failed = False
        self._blueprint_verified_prefixes: OrderedDict[str, _VerifiedPrefixLease] = OrderedDict()
        # These monotonic floors are deliberately not the bounded warm cache.
        # They prevent a valid, self-consistent older snapshot from becoming a
        # new trusted prefix after the WAL/data-version lease is invalidated.
        self._blueprint_attested_prefix_floors: dict[str, _VerifiedPrefixLease] = {}
        self._blueprint_transaction_guard = object()

    def _connect(self, *, check_same_thread: bool = True) -> sqlite3.Connection:
        connection = sqlite3.connect(
            self.db_path,
            timeout=5.0,
            factory=_MediaConnection,
            check_same_thread=check_same_thread,
        )
        connection._install_blueprint_read_transaction_tracking()
        connection.row_factory = sqlite3.Row
        connection.create_function(
            "memolens_canonical_json_sha256_without",
            2,
            _canonical_json_sha256_without,
            deterministic=True,
        )
        connection.create_function(
            "memolens_canonical_json_sha256",
            1,
            _canonical_json_sha256,
            deterministic=True,
        )
        connection.create_function(
            "memolens_blob_sha256",
            1,
            _sqlite_blob_sha256,
            deterministic=True,
        )
        connection.create_function(
            "memolens_validate_image_contract",
            2,
            _validate_image_contract_document,
            deterministic=True,
        )
        connection.create_function(
            "memolens_validate_projected_image_row",
            1,
            _validate_projected_image_row_document,
            deterministic=True,
        )
        connection.create_function(
            "memolens_validate_image_attempt_authority",
            1,
            _validate_image_attempt_authority_document,
            deterministic=True,
        )
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("PRAGMA busy_timeout=5000")
        journal = connection.execute("PRAGMA journal_mode=WAL").fetchone()[0]
        connection.execute("PRAGMA synchronous=NORMAL")
        foreign_keys = connection.execute("PRAGMA foreign_keys").fetchone()[0]
        if str(journal).casefold() != "wal" or int(foreign_keys) != 1:
            connection.close()
            raise MediaMigrationError("SQLite must support WAL and foreign keys.")
        return connection

    def close(self) -> None:
        """Release repository-lifetime descriptors, caches, and Blueprint state."""

        self._reset_blueprint_runtime_after_fork()
        try:
            with self._blueprint_anchor_lock:
                anchor = self._blueprint_anchor
                self._blueprint_anchor = None
                self._blueprint_anchor_identity = None
                self._blueprint_anchor_pid = None
                self._blueprint_verified_prefixes.clear()
                if anchor is not None:
                    try:
                        if anchor.in_transaction:
                            anchor.rollback()
                    finally:
                        anchor.close()
        finally:
            descriptors = tuple(self._output_root_descriptors.values())
            self._output_root_descriptors.clear()
            with self._prepared_export_roots_lock:
                descriptors += tuple(item[2] for item in self._prepared_export_roots.values())
                self._prepared_export_roots.clear()
            for descriptor in descriptors:
                try:
                    os.close(descriptor)
                except OSError:
                    pass
            with self._artifact_cache_lock:
                self._artifact_cache.clear()
            with self._source_cache_lock:
                self._source_cache.clear()
            with self._library_scan_runtime_leases_lock:
                self._library_scan_runtime_leases.clear()

    def _reset_blueprint_runtime_after_fork(self) -> None:
        """Replace inherited synchronization state before acquiring an old lock."""

        current_pid = os.getpid()
        if self._blueprint_runtime_pid == current_pid:
            return
        # Only the child reaches this branch. Replacing the lock before closing
        # the inherited connection avoids waiting forever on a lock owned by a
        # vanished parent thread.
        self._blueprint_anchor_lock = threading.RLock()
        self._blueprint_runtime_pid = current_pid
        self._blueprint_transaction_guard = object()
        self._library_scan_runtime_leases_lock = threading.Lock()
        self._library_scan_runtime_leases.clear()
        self._discard_blueprint_anchor()

    @contextmanager
    def transaction(self, *, immediate: bool = False) -> Iterator[sqlite3.Connection]:
        connection = self._connect()
        try:
            connection.execute("BEGIN IMMEDIATE" if immediate else "BEGIN")
            yield connection
            connection.commit()
        except Exception:
            connection.rollback()
            raise
        finally:
            connection.close()

    @contextmanager
    def _managed_connection(self) -> Iterator[sqlite3.Connection]:
        """Preserve sqlite3 context semantics and always release the handle."""

        connection = self._connect()
        try:
            with connection:
                yield connection
        finally:
            connection.close()

    @staticmethod
    def _verified_prefix_sqlite_is_safe() -> bool:
        """Use the single WAL-reset fixed-runtime gate for lease admission."""

        return is_wal_reset_safe(sqlite3.sqlite_version_info)

    def _blueprint_database_file_identity(self) -> tuple[int, int]:
        try:
            observed = os.stat(self.db_path, follow_symlinks=False)
        except OSError as exc:
            raise BlueprintIntegrityError("blueprint_database_identity_invalid") from exc
        if not stat.S_ISREG(observed.st_mode):
            raise BlueprintIntegrityError("blueprint_database_identity_invalid")
        return int(observed.st_dev), int(observed.st_ino)

    def _poison_blueprint_database_binding(self) -> None:
        """Permanently reject further Blueprint authority on this repository."""

        self._blueprint_database_binding_failed = True
        self._discard_blueprint_anchor()

    def _admit_blueprint_database_binding(self) -> tuple[int, int]:
        """Bind or verify the repository-lifetime database pathname identity."""

        try:
            identity = self._blueprint_database_file_identity()
        except BlueprintIntegrityError as exc:
            if self._blueprint_bound_database_identity is not None:
                self._poison_blueprint_database_binding()
                raise BlueprintIntegrityError("blueprint_database_binding_indeterminate") from exc
            raise
        bound = self._blueprint_bound_database_identity
        if bound is None:
            self._blueprint_bound_database_identity = identity
        elif identity != bound:
            self._poison_blueprint_database_binding()
            raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
        return identity

    def _verify_blueprint_connection_database_binding(
        self,
        connection: sqlite3.Connection,
        expected_identity: tuple[int, int],
    ) -> None:
        """Bind SQLite's canonical main filename to the repository pathname."""

        try:
            rows = connection.execute("PRAGMA database_list").fetchall()
            main_rows = [row for row in rows if str(row[1]).casefold() == "main"]
            if len(main_rows) != 1 or any(str(row[1]).casefold() not in {"main", "temp"} for row in rows):
                raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
            sqlite_filename = main_rows[0][2]
            if type(sqlite_filename) is not str or not sqlite_filename:
                raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
            opened_path = Path(sqlite_filename).expanduser().resolve(strict=True)
            if opened_path != self.db_path:
                raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
            before = self._blueprint_database_file_identity()
            if before != expected_identity:
                raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
            after = self._blueprint_database_file_identity()
            if after != expected_identity:
                raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
            admitted = getattr(
                connection,
                "_blueprint_bound_database_identity",
                expected_identity,
            )
            if admitted != expected_identity:
                raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
            connection._blueprint_bound_database_identity = expected_identity
        except Exception as exc:
            self._poison_blueprint_database_binding()
            if isinstance(exc, BlueprintIntegrityError):
                raise
            raise BlueprintIntegrityError("blueprint_database_binding_indeterminate") from exc

    def _connect_bound_blueprint(
        self,
        expected_identity: tuple[int, int],
        *,
        check_same_thread: bool = True,
    ) -> _MediaConnection:
        connection = self._connect(check_same_thread=check_same_thread)
        if not isinstance(connection, _MediaConnection):
            connection.close()
            self._poison_blueprint_database_binding()
            raise BlueprintIntegrityError("blueprint_transaction_connection_invalid")
        try:
            self._verify_blueprint_connection_database_binding(
                connection,
                expected_identity,
            )
        except Exception:
            try:
                connection.close()
            except sqlite3.Error:
                pass
            raise
        return connection

    @classmethod
    @lru_cache(maxsize=1)
    def _blueprint_allowed_main_schema_objects(
        cls,
    ) -> tuple[tuple[tuple[str, str, str, str], ...], ...]:
        reference = sqlite3.connect(":memory:")
        try:
            for statement in (
                IMAGE_INDEX_SCHEMA_STATEMENT,
                *IMAGE_INDEX_INDEX_STATEMENTS,
                *SCHEMA_STATEMENTS,
                *V3_SCHEMA_STATEMENTS,
                *V4_SCHEMA_STATEMENTS,
                *V5_SCHEMA_STATEMENTS,
                *V6_SCHEMA_STATEMENTS,
                *V7_SCHEMA_STATEMENTS,
                *V8_SCHEMA_STATEMENTS,
            ):
                reference.execute(statement)
            reference.commit()
            reference.execute("PRAGMA foreign_keys=OFF")
            reference.execute("PRAGMA legacy_alter_table=ON")
            reference.execute("BEGIN")
            cls._rebuild_v9_timeline_command_tables(reference)
            cls._rebuild_v11_agent_timeline_authority(reference)
            cls._rebuild_v12_agent_receipt_authority(reference)
            cls._rebuild_v13_timeline_restore_authority(reference)
            for statement in V14_SCHEMA_STATEMENTS:
                reference.execute(statement)
            cls._rebuild_v15_preview_authority(reference)
            for statement in V16_SCHEMA_STATEMENTS:
                reference.execute(statement)
            for statement in V17_SCHEMA_STATEMENTS:
                reference.execute(statement)
            cls._rebuild_v18_structural_edit_authority(reference)
            for statement in V19_SCHEMA_STATEMENTS:
                reference.execute(statement)
            for statement in V20_SCHEMA_STATEMENTS:
                reference.execute(statement)
            reference.commit()
            rows = reference.execute(
                """SELECT type,name,tbl_name,sql FROM sqlite_schema
                    WHERE type IN ('table','index','trigger','view')
                    ORDER BY type,name,tbl_name"""
            ).fetchall()
            base_schema = tuple(
                (
                    str(row[0]),
                    str(row[1]),
                    str(row[2]),
                    cls._normalized_schema_sql(row[3]),
                )
                for row in rows
            )
            reference.executescript(ATLAS_SCHEMA_SQL)
            rows_with_atlas = reference.execute(
                """SELECT type,name,tbl_name,sql FROM sqlite_schema
                    WHERE type IN ('table','index','trigger','view')
                    ORDER BY type,name,tbl_name"""
            ).fetchall()
        finally:
            reference.close()
        atlas_schema = tuple(
            (
                str(row[0]),
                str(row[1]),
                str(row[2]),
                cls._normalized_schema_sql(row[3]),
            )
            for row in rows_with_atlas
        )
        # Both variants are exact.  This permits an authenticated Atlas rebuild
        # to add its complete schema without weakening the data-only Blueprint
        # command boundary to arbitrary tables, columns, indexes, or triggers.
        return (base_schema, atlas_schema)

    @classmethod
    def _verify_blueprint_full_physical_schema(
        cls,
        connection: sqlite3.Connection,
    ) -> None:
        try:
            rows = connection.execute(
                """SELECT type,name,tbl_name,sql FROM main.sqlite_schema
                    WHERE type IN ('table','index','trigger','view')
                    ORDER BY type,name,tbl_name"""
            ).fetchall()
            observed = tuple(
                (
                    str(row[0]),
                    str(row[1]),
                    str(row[2]),
                    cls._normalized_schema_sql(row[3]),
                )
                for row in rows
            )
            if observed not in cls._blueprint_allowed_main_schema_objects():
                raise BlueprintIntegrityError("blueprint_schema_integrity_error")
            cls._verify_v4_physical_schema(connection)
            cls._verify_v5_post_v12_physical_schema(connection)
            cls._verify_v6_physical_schema(connection)
            cls._verify_v8_physical_schema(connection)
            cls._verify_v9_post_v18_physical_schema(connection)
            cls._verify_v11_post_v13_physical_schema(connection)
            cls._verify_v12_post_v13_physical_schema(connection)
            cls._verify_v14_physical_schema(
                connection,
                allow_v17_activation_trigger=True,
            )
            cls._verify_v16_physical_schema(connection)
            cls._verify_v17_physical_schema(connection)
            cls._verify_v18_physical_schema(connection)
            cls._verify_v19_physical_schema(connection)
            cls._verify_v20_physical_schema(connection)
        except (BlueprintIntegrityError, MediaMigrationError, sqlite3.Error) as exc:
            if isinstance(exc, BlueprintIntegrityError):
                raise
            raise BlueprintIntegrityError("blueprint_schema_integrity_error") from exc

    @classmethod
    def _blueprint_main_schema_snapshot(
        cls,
        connection: sqlite3.Connection,
    ) -> tuple[tuple[object, ...], ...]:
        """Capture the exact physical main-schema catalogue for one command."""

        try:
            rows = connection.execute(
                """SELECT rowid,type,name,tbl_name,rootpage,sql
                     FROM main.sqlite_schema ORDER BY rowid"""
            ).fetchall()
        except sqlite3.Error as exc:
            raise BlueprintIntegrityError("blueprint_schema_integrity_error") from exc
        return tuple(
            (
                int(row["rowid"]),
                str(row["type"]),
                str(row["name"]),
                str(row["tbl_name"]),
                int(row["rootpage"]),
                cls._normalized_schema_sql(row["sql"]),
            )
            for row in rows
        )

    @classmethod
    def _verify_blueprint_command_schema_boundary(
        cls,
        connection: sqlite3.Connection,
        *,
        expected_main_schema: tuple[tuple[object, ...], ...],
    ) -> None:
        """Re-establish data-only authority independently of SQLite callbacks."""

        try:
            if cls._schema_preflight(connection) != SCHEMA_VERSION:
                raise MediaMigrationError("blueprint_schema_version_mismatch")
            cls._verify_blueprint_full_physical_schema(connection)
            if cls._blueprint_main_schema_snapshot(connection) != expected_main_schema:
                raise BlueprintIntegrityError("blueprint_schema_integrity_error")
            if connection.execute("SELECT 1 FROM sqlite_temp_schema LIMIT 1").fetchone() is not None:
                raise BlueprintIntegrityError("blueprint_schema_integrity_error")
            databases = connection.execute("PRAGMA database_list").fetchall()
            names = [str(row[1]).casefold() for row in databases]
            if names.count("main") != 1 or any(name not in {"main", "temp"} for name in names):
                raise BlueprintIntegrityError("blueprint_schema_integrity_error")
        except (BlueprintIntegrityError, MediaMigrationError, sqlite3.Error) as exc:
            if isinstance(connection, _MediaConnection):
                connection._verified_prefix_connection_boundary_failed = True
            if isinstance(exc, BlueprintIntegrityError):
                raise
            raise BlueprintIntegrityError("blueprint_schema_integrity_error") from exc

    @staticmethod
    def _blueprint_observer_value(
        connection: sqlite3.Connection,
        pragma: str,
        *,
        database: str = "main",
    ) -> int:
        if (
            pragma not in {"data_version", "schema_version"}
            or database not in {"main", "temp"}
            or (pragma == "data_version" and database != "main")
        ):
            raise ValueError("unsupported_blueprint_observer_pragma")
        try:
            row = connection.execute(f"PRAGMA {database}.{pragma}").fetchone()
        except sqlite3.Error as exc:
            raise BlueprintIntegrityError("blueprint_observer_unavailable") from exc
        if row is None or type(row[0]) is not int or int(row[0]) < 0:
            raise BlueprintIntegrityError("blueprint_observer_unavailable")
        return int(row[0])

    def _discard_blueprint_anchor(self) -> None:
        anchor = self._blueprint_anchor
        self._blueprint_anchor = None
        self._blueprint_anchor_identity = None
        self._blueprint_anchor_pid = None
        self._blueprint_verified_prefixes.clear()
        if anchor is not None:
            try:
                if anchor.in_transaction:
                    anchor.rollback()
            except sqlite3.Error:
                pass
            try:
                anchor.close()
            except sqlite3.Error:
                pass

    def _blueprint_anchor_connection(self) -> tuple[_MediaConnection, tuple[int, int]]:
        current_pid = os.getpid()
        identity = self._admit_blueprint_database_binding()
        if self._blueprint_anchor is not None and self._blueprint_anchor_pid != current_pid:
            self._discard_blueprint_anchor()
        elif self._blueprint_anchor is not None and self._blueprint_anchor_identity != identity:
            # A repository that has already published Blueprint receipts must
            # never silently rebind to a different inode at the same pathname.
            self._poison_blueprint_database_binding()
            raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
        if self._blueprint_anchor is None:
            connection = self._connect_bound_blueprint(
                identity,
                check_same_thread=False,
            )
            connection._verified_prefix_transaction = None
            connection._verified_prefix_guard = self._blueprint_transaction_guard
            connection._verified_prefix_connection_boundary_failed = False
            self._blueprint_anchor = connection
            self._blueprint_anchor_identity = identity
            self._blueprint_anchor_pid = current_pid
        self._verify_blueprint_connection_database_binding(
            self._blueprint_anchor,
            identity,
        )
        return self._blueprint_anchor, identity

    @classmethod
    def _verified_prefix_transaction_context(
        cls,
        connection: sqlite3.Connection,
        project_id: str,
    ) -> _VerifiedPrefixTransaction | None:
        if not isinstance(connection, _MediaConnection) or not connection.in_transaction:
            return None
        context = getattr(connection, "_verified_prefix_transaction", None)
        if (
            not isinstance(context, _VerifiedPrefixTransaction)
            or context.lease.project_id != project_id
            or context.lease.process_id != os.getpid()
            or context.guard is not getattr(connection, "_verified_prefix_guard", None)
        ):
            return None
        return context

    def _remember_verified_prefix(self, lease: _VerifiedPrefixLease) -> None:
        self._blueprint_verified_prefixes.pop(lease.project_id, None)
        self._blueprint_verified_prefixes[lease.project_id] = lease
        while len(self._blueprint_verified_prefixes) > _BLUEPRINT_VERIFIED_PREFIX_MAX_PROJECTS:
            self._blueprint_verified_prefixes.popitem(last=False)

    @staticmethod
    @contextmanager
    def _blueprint_data_only_statement_scope(
        connection: sqlite3.Connection,
    ) -> Iterator[None]:
        """Prevent Blueprint callbacks from changing connection/schema authority."""

        if not isinstance(connection, _MediaConnection):
            raise BlueprintIntegrityError("blueprint_transaction_connection_invalid")
        connection._verified_prefix_authorizer_denied = False

        def command_authorizer(
            action: int,
            argument_one: str | None,
            argument_two: str | None,
            _database_name: str | None,
            _trigger_name: str | None,
        ) -> int:
            denied = action in _BLUEPRINT_FORBIDDEN_SQLITE_ACTIONS
            if action == sqlite3.SQLITE_PRAGMA:
                # Successor capture reads schema_version before returning from
                # the command. No mutation needs another PRAGMA, and every
                # PRAGMA assignment has a non-null second argument.
                denied = not (
                    argument_two is None
                    and isinstance(argument_one, str)
                    and argument_one.casefold() in {"schema_version", "data_version"}
                )
            elif action in {
                sqlite3.SQLITE_DELETE,
                sqlite3.SQLITE_INSERT,
                sqlite3.SQLITE_UPDATE,
            }:
                denied = isinstance(argument_one, str) and argument_one.casefold() in _BLUEPRINT_SCHEMA_TABLE_NAMES
            elif action == sqlite3.SQLITE_FUNCTION:
                function_name = argument_two or argument_one or ""
                denied = str(function_name).casefold() == "load_extension"
            if denied:
                connection._verified_prefix_authorizer_denied = True
                return sqlite3.SQLITE_DENY
            return sqlite3.SQLITE_OK

        connection.set_authorizer(command_authorizer)
        try:
            yield
        except sqlite3.DatabaseError as exc:
            if connection._verified_prefix_authorizer_denied:
                raise BlueprintIntegrityError("blueprint_schema_mutation_forbidden") from exc
            raise
        finally:
            connection.set_authorizer(None)
            connection._verified_prefix_authorizer_denied = False

    @contextmanager
    def _blueprint_command_callback_scope(
        self,
        connection: _MediaConnection,
    ) -> Iterator[None]:
        """Prove a mutation callback never crossed the outer transaction."""

        savepoint = f"memolens_blueprint_{uuid.uuid4().hex}"
        connection.execute(f'SAVEPOINT "{savepoint}"')
        connection._blueprint_transaction_control_protected = True
        try:
            with self._blueprint_data_only_statement_scope(connection):
                yield
        except BaseException as callback_error:
            connection._blueprint_transaction_control_protected = False
            try:
                if not connection.in_transaction:
                    raise sqlite3.OperationalError("blueprint callback ended the outer transaction")
                connection.execute(f'ROLLBACK TO SAVEPOINT "{savepoint}"')
                connection.execute(f'RELEASE SAVEPOINT "{savepoint}"')
            except sqlite3.Error:
                self._poison_blueprint_database_binding()
                raise BlueprintIntegrityError("blueprint_post_commit_verification_indeterminate") from callback_error
            raise
        else:
            connection._blueprint_transaction_control_protected = False
            try:
                if not connection.in_transaction:
                    raise sqlite3.OperationalError("blueprint callback ended the outer transaction")
                connection.execute(f'RELEASE SAVEPOINT "{savepoint}"')
            except sqlite3.Error as boundary_error:
                self._poison_blueprint_database_binding()
                raise BlueprintIntegrityError("blueprint_post_commit_verification_indeterminate") from boundary_error
        finally:
            connection._blueprint_transaction_control_protected = False

    @contextmanager
    def _fallback_verified_blueprint_command_transaction(
        self,
        project_id: str,
    ) -> Iterator[tuple[_MediaConnection, _VerifiedPrefixTransaction]]:
        """Run the cold-only path with the same exact successor contract."""

        with self._blueprint_anchor_lock:
            connection: _MediaConnection | None = None
            try:
                file_identity = self._admit_blueprint_database_binding()
                connection = self._connect_bound_blueprint(file_identity)
                connection._verified_prefix_guard = self._blueprint_transaction_guard
                connection._verified_prefix_transaction = None
                connection._verified_prefix_connection_boundary_failed = False
                connection.execute("BEGIN IMMEDIATE")
                self._verify_blueprint_connection_database_binding(
                    connection,
                    file_identity,
                )
                locked_version = self._blueprint_observer_value(
                    connection,
                    "data_version",
                )
                main_schema = self._blueprint_main_schema_snapshot(connection)
                self._verify_blueprint_command_schema_boundary(
                    connection,
                    expected_main_schema=main_schema,
                )
                admitted = self._full_audit_blueprint_prefix(
                    connection,
                    project_id,
                    data_version=locked_version,
                    file_identity=file_identity,
                )
                self._assert_blueprint_attested_floor_compatible(
                    connection,
                    admitted,
                )
                context = _VerifiedPrefixTransaction(
                    lease=admitted,
                    guard=self._blueprint_transaction_guard,
                    starting_total_changes=connection.total_changes,
                )
                connection._verified_prefix_transaction = context
                with self._blueprint_command_callback_scope(connection):
                    yield connection, context
                successor = context.successor
                if successor is None:
                    raise BlueprintIntegrityError("blueprint_verified_prefix_not_prepared")
                self._verify_blueprint_command_schema_boundary(
                    connection,
                    expected_main_schema=main_schema,
                )
                self._assert_blueprint_attested_floor_compatible(
                    connection,
                    successor,
                )
                self._verify_blueprint_connection_database_binding(
                    connection,
                    file_identity,
                )
                connection._verified_prefix_transaction = None
                audited_successor = self._full_audit_blueprint_prefix(
                    connection,
                    project_id,
                    data_version=locked_version,
                    file_identity=file_identity,
                )
                self._assert_blueprint_attested_floor_compatible(
                    connection,
                    audited_successor,
                )
                if (
                    replace(
                        audited_successor,
                        parent_attestation_sha256=successor.parent_attestation_sha256,
                    )
                    != successor
                ):
                    raise BlueprintIntegrityError("blueprint_command_delta_invalid")
                if self._admit_blueprint_database_binding() != file_identity:
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
                self._verify_blueprint_connection_database_binding(
                    connection,
                    file_identity,
                )
                connection.commit()
                if self._admit_blueprint_database_binding() != file_identity:
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
                try:
                    self._verify_blueprint_connection_database_binding(
                        connection,
                        file_identity,
                    )
                    post_version = self._blueprint_observer_value(
                        connection,
                        "data_version",
                    )
                    self._verify_blueprint_command_schema_boundary(
                        connection,
                        expected_main_schema=main_schema,
                    )
                except BlueprintIntegrityError as exc:
                    if str(exc) == "blueprint_database_binding_indeterminate":
                        raise
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_post_commit_verification_indeterminate") from exc
                except Exception as exc:
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_post_commit_verification_indeterminate") from exc
                if (
                    post_version != locked_version
                    or audited_successor.file_identity != file_identity
                    or audited_successor.process_id != os.getpid()
                ):
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_post_commit_verification_indeterminate")
                self._remember_blueprint_attested_floor(audited_successor)
            except Exception:
                if connection is not None:
                    try:
                        if connection.in_transaction:
                            connection.rollback()
                    except sqlite3.Error:
                        pass
                raise
            finally:
                if connection is not None:
                    connection._verified_prefix_transaction = None
                    connection.close()

    @contextmanager
    def _verified_blueprint_command_transaction(
        self,
        project_id: str,
    ) -> Iterator[tuple[sqlite3.Connection, _VerifiedPrefixTransaction | None]]:
        self._reset_blueprint_runtime_after_fork()
        if self._blueprint_database_binding_failed:
            raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
        if not self._verified_prefix_sqlite_is_safe():
            # The compatibility path never publishes a warm lease, but it has
            # the same repository-lifetime inode binding, cold physical audit,
            # monotonic prefix floor, and pre/post-commit boundary checks.
            with self._fallback_verified_blueprint_command_transaction(project_id) as transaction:
                yield transaction
            return

        with self._blueprint_anchor_lock:
            connection: _MediaConnection | None = None
            try:
                connection, file_identity = self._blueprint_anchor_connection()
                connection._verified_prefix_connection_boundary_failed = False
                before_lock_version = self._blueprint_observer_value(
                    connection,
                    "data_version",
                )
                connection.execute("BEGIN IMMEDIATE")
                self._verify_blueprint_connection_database_binding(
                    connection,
                    file_identity,
                )
                locked_version = self._blueprint_observer_value(
                    connection,
                    "data_version",
                )
                if before_lock_version != locked_version:
                    self._blueprint_verified_prefixes.clear()
                main_schema = self._blueprint_main_schema_snapshot(connection)
                self._verify_blueprint_command_schema_boundary(
                    connection,
                    expected_main_schema=main_schema,
                )
                lease = self._blueprint_verified_prefixes.get(project_id)
                if lease is not None and not self._verified_prefix_matches(
                    connection,
                    lease,
                    data_version=locked_version,
                    file_identity=file_identity,
                ):
                    self._blueprint_verified_prefixes.pop(project_id, None)
                    lease = None
                if lease is None:
                    lease = self._full_audit_blueprint_prefix(
                        connection,
                        project_id,
                        data_version=locked_version,
                        file_identity=file_identity,
                    )
                self._assert_blueprint_attested_floor_compatible(connection, lease)
                context = _VerifiedPrefixTransaction(
                    lease=lease,
                    guard=self._blueprint_transaction_guard,
                    starting_total_changes=connection.total_changes,
                )
                connection._verified_prefix_transaction = context
                with self._blueprint_command_callback_scope(connection):
                    yield connection, context
                successor = context.successor
                if successor is None:
                    raise BlueprintIntegrityError("blueprint_verified_prefix_not_prepared")
                current_schema_cookie = self._blueprint_observer_value(
                    connection,
                    "schema_version",
                )
                current_temp_schema_cookie = self._blueprint_observer_value(
                    connection,
                    "schema_version",
                    database="temp",
                )
                if (
                    current_schema_cookie != context.lease.schema_cookie
                    or successor.schema_cookie != context.lease.schema_cookie
                    or current_temp_schema_cookie != context.lease.temp_schema_cookie
                    or successor.temp_schema_cookie != context.lease.temp_schema_cookie
                ):
                    raise BlueprintIntegrityError("blueprint_schema_integrity_error")
                self._verify_blueprint_command_schema_boundary(
                    connection,
                    expected_main_schema=main_schema,
                )
                self._assert_blueprint_attested_floor_compatible(
                    connection,
                    successor,
                )
                if self._admit_blueprint_database_binding() != file_identity:
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
                self._verify_blueprint_connection_database_binding(
                    connection,
                    file_identity,
                )
                connection.commit()
                if self._admit_blueprint_database_binding() != file_identity:
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")
                try:
                    self._verify_blueprint_connection_database_binding(
                        connection,
                        file_identity,
                    )
                    post_version = self._blueprint_observer_value(
                        connection,
                        "data_version",
                    )
                    post_schema_cookie = self._blueprint_observer_value(
                        connection,
                        "schema_version",
                    )
                    post_temp_schema_cookie = self._blueprint_observer_value(
                        connection,
                        "schema_version",
                        database="temp",
                    )
                    self._verify_blueprint_command_schema_boundary(
                        connection,
                        expected_main_schema=main_schema,
                    )
                except BlueprintIntegrityError as exc:
                    if str(exc) == "blueprint_database_binding_indeterminate":
                        raise
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_post_commit_verification_indeterminate") from exc
                except Exception as exc:
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_post_commit_verification_indeterminate") from exc
                if (
                    post_version != locked_version
                    or post_schema_cookie != context.lease.schema_cookie
                    or post_temp_schema_cookie != context.lease.temp_schema_cookie
                    or successor.data_version != locked_version
                    or successor.file_identity != file_identity
                    or successor.total_changes != connection.total_changes
                    or successor.process_id != os.getpid()
                ):
                    self._blueprint_verified_prefixes.pop(project_id, None)
                    self._poison_blueprint_database_binding()
                    raise BlueprintIntegrityError("blueprint_post_commit_verification_indeterminate")
                self._remember_verified_prefix(successor)
                self._remember_blueprint_attested_floor(successor)
            except Exception:
                if connection is not None:
                    try:
                        if connection.in_transaction:
                            connection.rollback()
                    except sqlite3.Error:
                        self._discard_blueprint_anchor()
                if self._blueprint_database_binding_failed:
                    self._discard_blueprint_anchor()
                elif connection is not None and connection._verified_prefix_connection_boundary_failed:
                    self._discard_blueprint_anchor()
                self._blueprint_verified_prefixes.pop(project_id, None)
                raise
            finally:
                if connection is not None:
                    connection._verified_prefix_transaction = None

    @contextmanager
    def _verified_coverage_command_transaction(
        self,
        project_id: str,
    ) -> Iterator[tuple[sqlite3.Connection, _VerifiedPrefixTransaction | None]]:
        """Reuse the Blueprint trust boundary for a Coverage project write.

        Coverage owns a separate ledger, but it relies on the same database
        pathname, schema, TEMP/ATTACH, transaction-control, and post-commit
        authority guarantees.  Translate boundary failures to the Coverage
        error domain so API callers receive one stable fail-closed contract.
        """

        try:
            with self._verified_blueprint_command_transaction(project_id) as transaction:
                yield transaction
        except BlueprintIntegrityError as exc:
            raise CoverageIntegrityError(str(exc)) from exc

    @contextmanager
    def _verified_canonical_timeline_command_transaction(
        self,
        project_id: str,
    ) -> Iterator[tuple[sqlite3.Connection, _VerifiedPrefixTransaction | None]]:
        """Reuse the Blueprint boundary for one canonical Timeline write."""

        try:
            with self._verified_blueprint_command_transaction(project_id) as transaction:
                yield transaction
        except BlueprintIntegrityError as exc:
            raise CanonicalTimelineIntegrityError(str(exc)) from exc

    @classmethod
    def _blueprint_receipt_frontier(
        cls,
        connection: sqlite3.Connection,
        project_id: str,
        operation_id: str | None,
    ) -> tuple[object, ...] | None:
        if operation_id is None:
            return None
        desktop = connection.execute(
            """SELECT receipt.response_sha256,integrity.receipt_sha256
                 FROM blueprint_command_receipts receipt
                 JOIN blueprint_desktop_receipt_integrity integrity
                   ON integrity.project_id=receipt.project_id
                  AND integrity.operation_id=receipt.operation_id
                WHERE receipt.project_id=? AND receipt.operation_id=?""",
            (project_id, operation_id),
        ).fetchone()
        agent = connection.execute(
            """SELECT receipt.id,receipt.receipt_sha256,receipt.capability_id,
                      event.id AS event_id,event.sequence AS event_sequence,
                      event.event_sha256
                 FROM agent_project_command_receipts receipt
                 JOIN agent_project_capability_events event
                   ON event.agent_command_receipt_id=receipt.id
                  AND event.capability_id=receipt.capability_id
                  AND event.project_id=receipt.project_id
                WHERE receipt.project_id=? AND receipt.operation_id=?
                  AND receipt.receipt_schema_version='1'""",
            (project_id, operation_id),
        ).fetchone()
        if (desktop is None) == (agent is None):
            raise BlueprintIntegrityError("blueprint_receipt_ledger_incomplete")
        if desktop is not None:
            return (
                "desktop",
                operation_id,
                str(desktop["response_sha256"]),
                str(desktop["receipt_sha256"]),
            )
        assert agent is not None
        return (
            "agent",
            operation_id,
            str(agent["id"]),
            str(agent["receipt_sha256"]),
            str(agent["capability_id"]),
            str(agent["event_id"]),
            int(agent["event_sequence"]),
            str(agent["event_sha256"]),
        )

    @staticmethod
    def _blueprint_capability_frontier(
        connection: sqlite3.Connection,
        project_id: str,
    ) -> tuple[object, ...] | None:
        row = connection.execute(
            """SELECT capability_id,id,sequence,event_sha256
                 FROM agent_project_capability_events
                WHERE project_id=? ORDER BY rowid DESC LIMIT 1""",
            (project_id,),
        ).fetchone()
        if row is None:
            return None
        return (
            str(row["capability_id"]),
            str(row["id"]),
            int(row["sequence"]),
            str(row["event_sha256"]),
        )

    @staticmethod
    def _blueprint_table_prefix_seed(project_id: str, table: str) -> str:
        return hashlib.sha256(f"{_BLUEPRINT_PREFIX_DOMAIN}\0{project_id}\0{table}".encode()).hexdigest()

    @classmethod
    def _advance_blueprint_table_prefix_digest(
        cls,
        digest: str,
        *,
        table: str,
        row: sqlite3.Row,
    ) -> str:
        rowid = row["__memolens_prefix_rowid__"]
        if type(rowid) is not int or rowid < 1:
            raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid")
        columns: list[list[object]] = []
        for key in row.keys():
            if key == "__memolens_prefix_rowid__":
                continue
            value = row[key]
            if value is not None and type(value) not in {int, float, str}:
                raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid")
            columns.append([str(key), value])
        material = canonical_json(
            {
                "table": table,
                "rowid": rowid,
                "columns": columns,
            }
        ).encode()
        try:
            prior = bytes.fromhex(digest)
        except ValueError as exc:
            raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid") from exc
        if len(prior) != hashlib.sha256().digest_size:
            raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid")
        return hashlib.sha256(prior + b"\0" + material).hexdigest()

    @classmethod
    def _capture_blueprint_table_prefix(
        cls,
        connection: sqlite3.Connection,
        project_id: str,
        table: str,
        *,
        through_rowid: int | None = None,
    ) -> _AttestedTablePrefix:
        if table not in _BLUEPRINT_IMMUTABLE_PREFIX_TABLES:
            raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid")
        try:
            high_water_row = connection.execute(f"SELECT COALESCE(MAX(rowid),0) FROM {table}").fetchone()
        except sqlite3.Error as exc:
            raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid") from exc
        if high_water_row is None or type(high_water_row[0]) is not int or int(high_water_row[0]) < 0:
            raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid")
        current_high_water = int(high_water_row[0])
        if through_rowid is None:
            target_high_water = current_high_water
        else:
            if type(through_rowid) is not int or through_rowid < 0:
                raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid")
            if through_rowid > current_high_water:
                raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid")
            target_high_water = through_rowid
        digest = cls._blueprint_table_prefix_seed(project_id, table)
        row_count = 0
        try:
            rows = connection.execute(
                f"""SELECT rowid AS __memolens_prefix_rowid__,*
                       FROM {table}
                      WHERE project_id=? AND rowid<=? ORDER BY rowid""",
                (project_id, target_high_water),
            )
            for row in rows:
                digest = cls._advance_blueprint_table_prefix_digest(
                    digest,
                    table=table,
                    row=row,
                )
                row_count += 1
        except sqlite3.Error as exc:
            raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid") from exc
        return _AttestedTablePrefix(
            table=table,
            max_rowid=target_high_water,
            row_count=row_count,
            sha256=digest,
        )

    @classmethod
    def _capture_blueprint_immutable_prefixes(
        cls,
        connection: sqlite3.Connection,
        project_id: str,
    ) -> tuple[_AttestedTablePrefix, ...]:
        return tuple(
            cls._capture_blueprint_table_prefix(connection, project_id, table)
            for table in _BLUEPRINT_IMMUTABLE_PREFIX_TABLES
        )

    @classmethod
    def _advance_blueprint_immutable_prefixes(
        cls,
        connection: sqlite3.Connection,
        project_id: str,
        prior_prefixes: tuple[_AttestedTablePrefix, ...],
    ) -> tuple[_AttestedTablePrefix, ...]:
        if tuple(prefix.table for prefix in prior_prefixes) != (_BLUEPRINT_IMMUTABLE_PREFIX_TABLES):
            raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid")
        advanced: list[_AttestedTablePrefix] = []
        for prior in prior_prefixes:
            try:
                high_water_row = connection.execute(f"SELECT COALESCE(MAX(rowid),0) FROM {prior.table}").fetchone()
                if (
                    high_water_row is None
                    or type(high_water_row[0]) is not int
                    or int(high_water_row[0]) < prior.max_rowid
                ):
                    raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid")
                current_high_water = int(high_water_row[0])
                rows = connection.execute(
                    f"""SELECT rowid AS __memolens_prefix_rowid__,*
                           FROM {prior.table} NOT INDEXED
                          WHERE project_id=? AND rowid>? AND rowid<=?
                          ORDER BY rowid LIMIT ?""",
                    (
                        project_id,
                        prior.max_rowid,
                        current_high_water,
                        _BLUEPRINT_PREFIX_MAX_NEW_ROWS_PER_TABLE + 1,
                    ),
                ).fetchall()
            except BlueprintIntegrityError:
                raise
            except sqlite3.Error as exc:
                raise BlueprintIntegrityError("blueprint_prefix_commitment_invalid") from exc
            if len(rows) > _BLUEPRINT_PREFIX_MAX_NEW_ROWS_PER_TABLE:
                raise BlueprintIntegrityError("blueprint_command_delta_invalid")
            digest = prior.sha256
            for row in rows:
                digest = cls._advance_blueprint_table_prefix_digest(
                    digest,
                    table=prior.table,
                    row=row,
                )
            advanced.append(
                _AttestedTablePrefix(
                    table=prior.table,
                    max_rowid=current_high_water,
                    row_count=prior.row_count + len(rows),
                    sha256=digest,
                )
            )
        return tuple(advanced)

    @staticmethod
    def _blueprint_lease_attestation_sha256(lease: _VerifiedPrefixLease) -> str:
        return content_sha256(
            {
                "object": "memolens.blueprint.prefix-attestation.v1",
                "database_uuid": lease.database_uuid,
                "project_id": lease.project_id,
                "operation_sequence": lease.operation_sequence,
                "operation_id": lease.operation_id,
                "immutable_prefixes": [
                    {
                        "table": prefix.table,
                        "max_rowid": prefix.max_rowid,
                        "row_count": prefix.row_count,
                        "sha256": prefix.sha256,
                    }
                    for prefix in lease.immutable_prefixes
                ],
            }
        )

    def _assert_blueprint_immutable_floor(
        self,
        connection: sqlite3.Connection,
        floor: _VerifiedPrefixLease,
    ) -> None:
        if tuple(prefix.table for prefix in floor.immutable_prefixes) != (_BLUEPRINT_IMMUTABLE_PREFIX_TABLES):
            self._reject_blueprint_attested_floor()
        for expected in floor.immutable_prefixes:
            observed = self._capture_blueprint_table_prefix(
                connection,
                floor.project_id,
                expected.table,
                through_rowid=expected.max_rowid,
            )
            if observed != expected:
                self._reject_blueprint_attested_floor()

    def _remember_blueprint_attested_floor(self, lease: _VerifiedPrefixLease) -> None:
        self._blueprint_attested_prefix_floors[lease.project_id] = lease

    def _reject_blueprint_attested_floor(self) -> None:
        self._poison_blueprint_database_binding()
        raise BlueprintIntegrityError("blueprint_database_binding_indeterminate")

    def _assert_blueprint_attested_floor_compatible(
        self,
        connection: sqlite3.Connection,
        candidate: _VerifiedPrefixLease,
    ) -> None:
        """Prove a cold/current prefix still contains the last trusted prefix."""

        floor = self._blueprint_attested_prefix_floors.get(candidate.project_id)
        if floor is None or floor is candidate:
            return
        if candidate.database_uuid != floor.database_uuid or candidate.operation_sequence < floor.operation_sequence:
            self._reject_blueprint_attested_floor()
        if tuple(prefix.table for prefix in candidate.immutable_prefixes) != tuple(
            prefix.table for prefix in floor.immutable_prefixes
        ):
            self._reject_blueprint_attested_floor()
        trusted_incremental_extension = candidate.parent_attestation_sha256 == self._blueprint_lease_attestation_sha256(
            floor
        )
        if not trusted_incremental_extension:
            self._assert_blueprint_immutable_floor(connection, floor)
        for previous, current in zip(
            floor.immutable_prefixes,
            candidate.immutable_prefixes,
            strict=True,
        ):
            if (
                current.max_rowid < previous.max_rowid
                or current.row_count < previous.row_count
                or (current.row_count == previous.row_count and current.sha256 != previous.sha256)
            ):
                self._reject_blueprint_attested_floor()

        if floor.operation_id is None:
            if floor.operation_sequence != 0 or floor.operation is not None:
                self._reject_blueprint_attested_floor()
        else:
            operation_row = connection.execute(
                """SELECT * FROM creative_blueprint_operations
                    WHERE project_id=? AND sequence=?""",
                (candidate.project_id, floor.operation_sequence),
            ).fetchone()
            if operation_row is None or (self._blueprint_operation_from_row(operation_row) != floor.operation):
                self._reject_blueprint_attested_floor()
            try:
                receipt_frontier = self._blueprint_receipt_frontier(
                    connection,
                    candidate.project_id,
                    floor.operation_id,
                )
            except BlueprintIntegrityError:
                self._reject_blueprint_attested_floor()
            if receipt_frontier != floor.receipt_frontier:
                self._reject_blueprint_attested_floor()

        if floor.head is None:
            if floor.operation_sequence != 0:
                self._reject_blueprint_attested_floor()
        elif candidate.operation_sequence == floor.operation_sequence:
            if candidate.head != floor.head:
                self._reject_blueprint_attested_floor()
        else:
            historical = self.get_blueprint_revision_in_transaction(
                connection,
                candidate.project_id,
                int(floor.head["revision"]),
                content_sha256=str(floor.head["content_sha256"]),
                _validate_ledger=False,
            )
            expected_historical = deepcopy(floor.head)
            expected_historical.pop("head_updated_at", None)
            if historical != expected_historical:
                self._reject_blueprint_attested_floor()

        capability_frontier = floor.capability_frontier
        if capability_frontier is not None:
            capability_id, event_id, sequence, event_sha256 = capability_frontier
            event = connection.execute(
                """SELECT capability_id,id,sequence,event_sha256
                     FROM agent_project_capability_events
                    WHERE project_id=? AND id=?""",
                (candidate.project_id, event_id),
            ).fetchone()
            if event is None or (
                str(event["capability_id"]),
                str(event["id"]),
                int(event["sequence"]),
                str(event["event_sha256"]),
            ) != (
                capability_id,
                event_id,
                sequence,
                event_sha256,
            ):
                self._reject_blueprint_attested_floor()

    @classmethod
    def _capture_blueprint_project_state(
        cls,
        connection: sqlite3.Connection,
        project_id: str,
    ) -> _BlueprintProjectState:
        row = connection.execute(
            """SELECT id,title,status,created_at,updated_at
                 FROM creative_projects WHERE id=?""",
            (project_id,),
        ).fetchone()
        if (
            row is None
            or any(type(row[key]) is not str for key in row.keys())
            or str(row["id"]) != project_id
            or str(row["status"]) not in {"draft", "active", "archived"}
            or not cls._is_utc_timestamp(row["created_at"])
            or not cls._is_utc_timestamp(row["updated_at"])
        ):
            raise BlueprintIntegrityError("blueprint_project_state_invalid")
        return _BlueprintProjectState(
            project_id=str(row["id"]),
            title=str(row["title"]),
            status=str(row["status"]),
            created_at=str(row["created_at"]),
            updated_at=str(row["updated_at"]),
        )

    def _capture_verified_blueprint_prefix(
        self,
        connection: sqlite3.Connection,
        project_id: str,
        *,
        head: dict[str, object] | None,
        data_version: int,
        file_identity: tuple[int, int],
        immutable_prefixes: tuple[_AttestedTablePrefix, ...] | None = None,
        parent_attestation_sha256: str | None = None,
    ) -> _VerifiedPrefixLease:
        meta = connection.execute("SELECT database_uuid,schema_version FROM database_meta WHERE singleton=1").fetchone()
        if (
            meta is None
            or int(meta["schema_version"]) != SCHEMA_VERSION
            or not self._is_blueprint_identifier(meta["database_uuid"])
        ):
            raise BlueprintIntegrityError("blueprint_database_identity_invalid")
        latest = connection.execute(
            """SELECT * FROM creative_blueprint_operations
                WHERE project_id=? ORDER BY sequence DESC LIMIT 1""",
            (project_id,),
        ).fetchone()
        operation_sequence = int(latest["sequence"]) if latest is not None else 0
        operation_id = str(latest["id"]) if latest is not None else None
        operation = self._blueprint_operation_from_row(latest) if latest is not None else None
        if (operation_sequence == 0) != (head is None):
            raise BlueprintIntegrityError("blueprint_ledger_cardinality_invalid")
        receipt_frontier = self._blueprint_receipt_frontier(
            connection,
            project_id,
            operation_id,
        )
        capability_frontier = self._blueprint_capability_frontier(
            connection,
            project_id,
        )
        resolved_prefixes = (
            immutable_prefixes
            if immutable_prefixes is not None
            else self._capture_blueprint_immutable_prefixes(connection, project_id)
        )
        return _VerifiedPrefixLease(
            process_id=os.getpid(),
            database_uuid=str(meta["database_uuid"]),
            schema_version=int(meta["schema_version"]),
            schema_cookie=self._blueprint_observer_value(connection, "schema_version"),
            temp_schema_cookie=self._blueprint_observer_value(
                connection,
                "schema_version",
                database="temp",
            ),
            project_id=project_id,
            head=deepcopy(head),
            project_state=self._capture_blueprint_project_state(
                connection,
                project_id,
            ),
            operation_sequence=operation_sequence,
            operation_id=operation_id,
            operation=operation,
            receipt_frontier=receipt_frontier,
            capability_frontier=capability_frontier,
            data_version=data_version,
            total_changes=connection.total_changes,
            file_identity=file_identity,
            immutable_prefixes=resolved_prefixes,
            parent_attestation_sha256=parent_attestation_sha256,
        )

    def _verified_prefix_matches(
        self,
        connection: sqlite3.Connection,
        lease: _VerifiedPrefixLease,
        *,
        data_version: int,
        file_identity: tuple[int, int],
    ) -> bool:
        if (
            lease.process_id != os.getpid()
            or lease.data_version != data_version
            or lease.total_changes != connection.total_changes
            or lease.file_identity != file_identity
            or lease.schema_version != SCHEMA_VERSION
            or lease.schema_cookie != self._blueprint_observer_value(connection, "schema_version")
            or lease.temp_schema_cookie
            != self._blueprint_observer_value(
                connection,
                "schema_version",
                database="temp",
            )
        ):
            return False
        meta = connection.execute("SELECT database_uuid,schema_version FROM database_meta WHERE singleton=1").fetchone()
        if (
            meta is None
            or str(meta["database_uuid"]) != lease.database_uuid
            or int(meta["schema_version"]) != lease.schema_version
        ):
            return False
        head = connection.execute(
            "SELECT * FROM creative_blueprint_heads WHERE project_id=?",
            (lease.project_id,),
        ).fetchone()
        if lease.head is None:
            if head is not None:
                return False
        elif head is None or (
            any(
                head[key] != lease.head[key]
                for key in (
                    "project_id",
                    "revision",
                    "content_sha256",
                    "semantic_sha256",
                    "operation_id",
                )
            )
            or head["updated_at"] != lease.head.get("head_updated_at")
        ):
            return False
        latest = connection.execute(
            """SELECT id,sequence FROM creative_blueprint_operations
                WHERE project_id=? ORDER BY sequence DESC LIMIT 1""",
            (lease.project_id,),
        ).fetchone()
        if lease.operation_id is None:
            if latest is not None:
                return False
        elif (
            latest is None or latest["id"] != lease.operation_id or int(latest["sequence"]) != lease.operation_sequence
        ):
            return False
        try:
            receipt_frontier = self._blueprint_receipt_frontier(
                connection,
                lease.project_id,
                lease.operation_id,
            )
        except BlueprintIntegrityError:
            return False
        if receipt_frontier != lease.receipt_frontier:
            return False
        if self._blueprint_capability_frontier(connection, lease.project_id) != lease.capability_frontier:
            return False
        if self._capture_blueprint_project_state(connection, lease.project_id) != lease.project_state:
            return False
        return True

    def _full_audit_blueprint_prefix(
        self,
        connection: sqlite3.Connection,
        project_id: str,
        *,
        data_version: int,
        file_identity: tuple[int, int],
    ) -> _VerifiedPrefixLease:
        try:
            if self._schema_preflight(connection) != SCHEMA_VERSION:
                raise BlueprintIntegrityError("blueprint_database_identity_invalid")
            self._verify_blueprint_full_physical_schema(connection)
        except MediaMigrationError as exc:
            raise BlueprintIntegrityError("blueprint_schema_integrity_error") from exc
        head = self.get_blueprint_head_in_transaction(connection, project_id)
        try:
            self._validate_coverage_ledger_in_transaction(connection, project_id)
        except CoverageIntegrityError as exc:
            raise BlueprintIntegrityError("blueprint_dependent_coverage_integrity_invalid") from exc
        try:
            self._validate_canonical_timeline_ledger_in_transaction(
                connection,
                project_id,
            )
        except CanonicalTimelineIntegrityError as exc:
            raise BlueprintIntegrityError("blueprint_dependent_timeline_integrity_invalid") from exc
        try:
            self._validate_canonical_export_ledger_in_transaction(
                connection,
                project_id,
            )
        except CanonicalExportIntegrityError as exc:
            raise BlueprintIntegrityError("blueprint_dependent_export_integrity_invalid") from exc
        return self._capture_verified_blueprint_prefix(
            connection,
            project_id,
            head=head,
            data_version=data_version,
            file_identity=file_identity,
        )

    def _begin_verified_schema_migration(  # noqa: C901 - ordered historical-schema admission matrix
        self,
        connection: sqlite3.Connection,
    ) -> int:
        observed_version = self._schema_preflight(connection)
        if observed_version < 18:
            # SQLite only honors foreign_keys changes outside a transaction.
            # Rebuilding managed authority tables then rechecks the exact source under
            # BEGIN IMMEDIATE before backup or DDL, so TOCTOU fails closed.
            connection.execute("PRAGMA foreign_keys=OFF")
            connection.execute("PRAGMA legacy_alter_table=ON")
        connection.execute("BEGIN IMMEDIATE")
        previous_version = self._schema_preflight(connection)
        if previous_version != observed_version:
            raise MediaMigrationError("managed_schema_changed_during_migration")
        if previous_version < 4:
            self._reject_v4_schema_name_collisions(connection)
        else:
            self._verify_v4_physical_schema(connection)
        if previous_version < 5:
            self._reject_v5_schema_name_collisions(connection)
        elif previous_version < 11:
            self._verify_v5_physical_schema(connection)
        elif previous_version < 12:
            self._verify_v5_unreplaced_physical_schema(connection)
        else:
            self._verify_v5_post_v12_physical_schema(connection)
        if previous_version == 11:
            self._verify_v11_physical_schema(connection)
        elif previous_version == 12:
            self._verify_v11_unreplaced_physical_schema(connection)
            self._verify_v12_physical_schema(connection)
        elif previous_version >= 13:
            self._verify_v11_post_v13_physical_schema(connection)
            self._verify_v12_post_v13_physical_schema(connection)
            if previous_version < 15:
                self._verify_v13_physical_schema(connection)
            elif previous_version < 18:
                self._verify_v13_post_v15_physical_schema(connection)
                self._verify_v15_physical_schema(connection)
            else:
                self._verify_v18_physical_schema(connection)
        if previous_version < 6:
            self._reject_v6_schema_name_collisions(connection)
        else:
            self._verify_v6_physical_schema(connection)
        if previous_version < 7:
            self._reject_v7_schema_name_collisions(connection)
        elif previous_version < 9:
            self._verify_v7_physical_schema(connection)
        elif previous_version < 13:
            self._verify_v9_physical_schema(connection)
        elif previous_version < 18:
            self._verify_v9_post_v13_physical_schema(connection)
        else:
            self._verify_v9_post_v18_physical_schema(connection)
        if previous_version < 8:
            self._reject_v8_schema_name_collisions(connection)
        else:
            self._verify_v8_physical_schema(connection)
        if previous_version < 14:
            if previous_version > 0:
                self._validate_v14_canonical_asset_identity_source(connection)
            self._reject_v14_schema_name_collisions(connection)
        else:
            self._verify_v14_physical_schema(
                connection,
                allow_v17_activation_trigger=previous_version >= 17,
            )
        if previous_version < 15:
            self._reject_v15_schema_name_collisions(connection)
        elif previous_version < 18:
            self._verify_v15_physical_schema(connection)
        self._verify_v16_schema_source(connection, previous_version)
        self._verify_v17_schema_source(connection, previous_version)
        self._verify_v18_schema_source(connection, previous_version)
        self._verify_v19_schema_source(connection, previous_version)
        self._verify_v20_schema_source(connection, previous_version)
        if previous_version == 3:
            self._backup_v3_database(connection)
        elif previous_version == 4:
            self._backup_v4_database(connection)
        elif previous_version == 5:
            self._backup_v5_database(connection)
        elif previous_version == 6:
            self._backup_v6_database(connection)
        elif previous_version == 7:
            self._backup_v7_database(connection)
        elif previous_version == 8:
            self._backup_v8_database(connection)
        elif previous_version == 10:
            self._backup_v10_database(connection)
        elif previous_version == 11:
            self._reject_v12_receipt_source_collisions(connection)
            self._validate_v11_receipt_authority_before_migration(connection)
            self._backup_v11_database(connection)
        elif previous_version == 12:
            self._reject_v13_schema_name_collisions(connection)
            self._validate_v12_receipt_authority_before_migration(connection)
            self._backup_v12_database(connection)
        elif previous_version == 13:
            self._backup_v13_database(connection)
        elif previous_version == 14:
            self._validate_v13_timeline_restore_authority_after_migration(connection)
            self._backup_v14_database(connection)
        self._backup_v15_schema_source_if_needed(connection, previous_version)
        self._backup_v16_schema_source_if_needed(connection, previous_version)
        if previous_version == 17:
            self._validate_v13_timeline_restore_authority_after_migration(connection)
            self._backup_v17_database(connection)
        elif previous_version == 18:
            self._validate_v13_timeline_restore_authority_after_migration(connection)
            self._backup_v18_database(connection)
        elif previous_version == 19:
            self._validate_v18_structural_edit_authority_after_migration(connection)
            self._backup_v19_database(connection)
        return previous_version

