    @staticmethod
    def _validate_v14_canonical_asset_identity_source(
        connection: sqlite3.Connection,
    ) -> None:
        """Reject a damaged pre-V14 source that already split content identity."""

        try:
            duplicate = connection.execute(
                """SELECT sha256
                     FROM assets
                    GROUP BY sha256
                   HAVING COUNT(*)>1
                    LIMIT 1"""
            ).fetchone()
        except sqlite3.Error as exc:
            raise MediaMigrationError(
                "v14_canonical_asset_identity_audit_unavailable"
            ) from exc
        if duplicate is not None:
            raise MediaMigrationError(
                "v14_duplicate_canonical_asset_identity"
            )

    @classmethod
    def _validate_v11_receipt_authority_before_migration(
        cls,
        connection: sqlite3.Connection,
    ) -> None:
        """Cold-audit the exact V11 source before backup or convergence copy."""

        try:
            cls._validate_agent_project_command_receipt_census(connection)
            projects = connection.execute(
                """SELECT DISTINCT project_id FROM (
                       SELECT project_id FROM agent_project_capabilities
                       UNION ALL
                       SELECT project_id FROM agent_blueprint_command_receipts
                       UNION ALL
                       SELECT project_id FROM agent_project_command_receipts
                       UNION ALL
                       SELECT project_id FROM agent_project_capability_events
                   ) ORDER BY project_id"""
            ).fetchall()
            for project in projects:
                project_id = project["project_id"]
                if not cls._is_blueprint_identifier(project_id):
                    raise BlueprintIntegrityError("agent_capability_ledger_incomplete")
                cls._validate_blueprint_receipt_ledger(
                    connection,
                    str(project_id),
                )
            capability_rows = connection.execute("SELECT id FROM agent_project_capabilities ORDER BY id").fetchall()
            for capability_row in capability_rows:
                state = cls._validated_capability_state(
                    connection,
                    str(capability_row["id"]),
                    runtime_authority_epoch=None,
                )
                if state is None:
                    raise BlueprintIntegrityError("agent_capability_ledger_incomplete")
        except (BlueprintIntegrityError, CanonicalTimelineIntegrityError) as exc:
            raise MediaMigrationError("v11_agent_authority_audit_failed") from exc
        except sqlite3.Error as exc:
            raise MediaMigrationError("v11_agent_authority_audit_unavailable") from exc

