    def _migrate_v17_image_read_cutover(
        self,
        connection: sqlite3.Connection,
        previous_version: int,
    ) -> None:
        if previous_version < 17:
            for statement in V17_SCHEMA_STATEMENTS:
                connection.execute(statement)
            self._verify_v17_physical_schema(connection)
            self._backfill_v17_active_read_manifest_in_transaction(connection)
        self._verify_v14_physical_schema(
            connection,
            allow_v17_activation_trigger=True,
        )
        self._verify_v17_physical_schema(connection)
        self._migration(
            connection,
            17,
            "canonical_image_read_cutover",
            V17_CHECKSUM,
        )

