    def ensure_schema(  # noqa: C901 - ordered append-only migration coordinator
        self,
        default_library_root: Path | None = None,
    ) -> None:
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        connection = self._connect()
        foreign_keys_before = int(connection.execute("PRAGMA foreign_keys").fetchone()[0])
        legacy_alter_table_before = int(connection.execute("PRAGMA legacy_alter_table").fetchone()[0])
        try:
            previous_version = self._begin_verified_schema_migration(connection)
            for statement in SCHEMA_STATEMENTS:
                connection.execute(statement)
            self._migration(connection, 1, "image_index_baseline", BASELINE_CHECKSUM)
            self._migration(connection, 2, "video_creative_workbench", V2_CHECKSUM)
            for statement in V3_SCHEMA_STATEMENTS:
                connection.execute(statement)
            self._migration(connection, 3, "creator_memory_media_inbox", V3_CHECKSUM)
            for statement in V4_SCHEMA_STATEMENTS:
                connection.execute(statement)
            self._verify_v4_physical_schema(connection)
            self._migration(
                connection,
                4,
                "canonical_blueprint_proposal_ledger",
                V4_CHECKSUM,
            )
            retired_v5_statement_indexes = {2, 11, 18, 19}
            for index, statement in enumerate(V5_SCHEMA_STATEMENTS):
                if previous_version >= 12 and index in retired_v5_statement_indexes:
                    continue
                connection.execute(statement)
            if previous_version == 4:
                self._backfill_v5_desktop_receipt_integrity(connection)
            self._validate_all_desktop_receipt_integrity(connection)
            if previous_version < 11:
                self._verify_v5_physical_schema(connection)
            elif previous_version < 12:
                self._verify_v5_unreplaced_physical_schema(connection)
            else:
                self._verify_v5_post_v12_physical_schema(connection)
            self._migration(
                connection,
                5,
                "paired_agent_decision_authority",
                V5_CHECKSUM,
            )
            for statement in V6_SCHEMA_STATEMENTS:
                connection.execute(statement)
            self._verify_v6_physical_schema(connection)
            self._migration(
                connection,
                6,
                "canonical_coverage_plan_baseline",
                V6_CHECKSUM,
            )
            for statement in V7_SCHEMA_STATEMENTS:
                connection.execute(statement)
            if previous_version < 9:
                self._verify_v7_physical_schema(connection)
            self._migration(
                connection,
                7,
                "canonical_timeline_first_cut",
                V7_CHECKSUM,
            )
            for statement in V8_SCHEMA_STATEMENTS:
                connection.execute(statement)
            self._verify_v8_physical_schema(connection)
            self._migration(
                connection,
                8,
                "canonical_export_usage_ledger",
                V8_CHECKSUM,
            )
            if previous_version < 9:
                self._rebuild_v9_timeline_command_tables(connection)
            if previous_version < 13:
                self._verify_v9_physical_schema(connection)
            elif previous_version < 18:
                self._verify_v9_post_v13_physical_schema(connection)
            else:
                self._verify_v9_post_v18_physical_schema(connection)
            self._migration(
                connection,
                9,
                "canonical_timeline_reconciliation",
                V9_CHECKSUM,
            )
            self._migration(
                connection,
                10,
                "canonical_timeline_persistent_edit",
                V10_CHECKSUM,
            )
            if previous_version < 11:
                self._rebuild_v11_agent_timeline_authority(connection)
            if previous_version < 12:
                self._verify_v5_unreplaced_physical_schema(connection)
                self._verify_v11_physical_schema(connection)
            elif previous_version < 13:
                self._verify_v5_post_v12_physical_schema(connection)
                self._verify_v11_unreplaced_physical_schema(connection)
                self._verify_v12_physical_schema(connection)
            else:
                self._verify_v5_post_v12_physical_schema(connection)
                self._verify_v11_post_v13_physical_schema(connection)
                self._verify_v12_post_v13_physical_schema(connection)
                self._verify_v13_authority_schema_for_source(
                    connection,
                    previous_version,
                )
            self._migration(
                connection,
                11,
                "paired_agent_canonical_timeline_edit",
                V11_CHECKSUM,
            )
            if previous_version < 12:
                self._validate_v11_receipt_authority_before_migration(connection)
                self._rebuild_v12_agent_receipt_authority(connection)
            self._verify_v5_post_v12_physical_schema(connection)
            if previous_version < 13:
                self._verify_v11_unreplaced_physical_schema(connection)
                self._verify_v12_physical_schema(connection)
            else:
                self._verify_v11_post_v13_physical_schema(connection)
                self._verify_v12_post_v13_physical_schema(connection)
                self._verify_v13_authority_schema_for_source(
                    connection,
                    previous_version,
                )
            self._migration(
                connection,
                12,
                "paired_agent_project_command_receipt_convergence",
                V12_CHECKSUM,
            )
            if previous_version < 13:
                intermediate_now = utc_now_iso()
                connection.execute(
                    """INSERT INTO database_meta(
                         singleton,database_uuid,schema_version,created_at,updated_at)
                       VALUES(1,?,12,?,?) ON CONFLICT(singleton) DO UPDATE SET
                       schema_version=12,updated_at=excluded.updated_at""",
                    (str(uuid.uuid4()), intermediate_now, intermediate_now),
                )
                self._validate_v12_receipt_authority_before_migration(connection)
                self._rebuild_v13_timeline_restore_authority(connection)
            self._verify_v5_post_v12_physical_schema(connection)
            if previous_version < 18:
                self._verify_v9_post_v13_physical_schema(connection)
            else:
                self._verify_v9_post_v18_physical_schema(connection)
            self._verify_v11_post_v13_physical_schema(connection)
            self._verify_v12_post_v13_physical_schema(connection)
            self._verify_v13_authority_schema_for_source(
                connection,
                previous_version,
            )
            self._migration(
                connection,
                13,
                "paired_agent_canonical_timeline_restore",
                V13_CHECKSUM,
            )
            if previous_version < 14:
                for statement in V14_SCHEMA_STATEMENTS:
                    connection.execute(statement)
            self._verify_v14_physical_schema(
                connection,
                allow_v17_activation_trigger=previous_version >= 17,
            )
            self._migration(
                connection,
                14,
                "canonical_image_publication_bridge",
                V14_CHECKSUM,
            )
            if previous_version < 15:
                self._rebuild_v15_preview_authority(connection)
            if previous_version < 18:
                self._verify_v13_post_v15_physical_schema(connection)
                self._verify_v15_physical_schema(connection)
            else:
                self._verify_v18_physical_schema(connection)
            self._migration(
                connection,
                15,
                "paired_agent_timeline_preview_media",
                V15_CHECKSUM,
            )
            if previous_version < 16:
                for statement in V16_SCHEMA_STATEMENTS:
                    connection.execute(statement)
            self._verify_v16_physical_schema(connection)
            self._migration(
                connection,
                16,
                "provider_egress_one_shot_authority",
                V16_CHECKSUM,
            )
            self._migrate_v17_image_read_cutover(
                connection,
                previous_version,
            )
            self._migrate_v18_structural_edit_authority(
                connection,
                previous_version,
            )
            self._migrate_v19_export_root_anchor(
                connection,
                previous_version,
            )
            self._migrate_v20_library_bootstrap(
                connection,
                previous_version,
            )
            now = utc_now_iso()
            connection.execute(
                """INSERT INTO database_meta(singleton,database_uuid,schema_version,created_at,updated_at)
                   VALUES(1,?,?,?,?) ON CONFLICT(singleton) DO UPDATE SET
                   schema_version=excluded.schema_version,updated_at=excluded.updated_at""",
                (str(uuid.uuid4()), SCHEMA_VERSION, now, now),
            )
            self._validate_v18_structural_edit_authority_after_migration(connection)
            # Opening a managed database never promotes legacy ``image_index`` observations into
            # canonical assets/sources during startup.  Historical rows must
            # cross the explicit descriptor-verified legacy backfill route;
            # reopening a database is not an evidence-producing action.
            if default_library_root is not None:
                self._upsert_library_root(connection, default_library_root.resolve())
            foreign_key_errors = connection.execute("PRAGMA foreign_key_check").fetchall()
            if foreign_key_errors:
                raise MediaMigrationError("foreign_key_check_failed")
            integrity = connection.execute("PRAGMA integrity_check").fetchone()
            if not integrity or str(integrity[0]).casefold() != "ok":
                raise MediaMigrationError("integrity_check_failed")
            connection.commit()
        except Exception:
            connection.rollback()
            raise
        finally:
            if not connection.in_transaction:
                connection.execute(f"PRAGMA legacy_alter_table={legacy_alter_table_before}")
                connection.execute(f"PRAGMA foreign_keys={foreign_keys_before}")
            connection.close()

    @staticmethod
    def _schema_object_exists(
        connection: sqlite3.Connection,
        *,
        object_type: str,
        name: str,
    ) -> bool:
        return (
            connection.execute(
                "SELECT 1 FROM sqlite_master WHERE type=? AND name=?",
                (object_type, name),
            ).fetchone()
            is not None
        )

    @classmethod
    def _schema_preflight(cls, connection: sqlite3.Connection) -> int:
        """Reject unrecognized or damaged managed schemas before executing DDL."""

        migrations_exist = cls._schema_object_exists(
            connection,
            object_type="table",
            name="schema_migrations",
        )
        meta_exists = cls._schema_object_exists(
            connection,
            object_type="table",
            name="database_meta",
        )
        if not migrations_exist and not meta_exists:
            return 0
        if migrations_exist != meta_exists:
            raise MediaMigrationError("managed_schema_metadata_incomplete")

        migration_rows = connection.execute(
            "SELECT version,name,checksum FROM schema_migrations ORDER BY version"
        ).fetchall()
        versions: set[int] = set()
        for row in migration_rows:
            version = int(row["version"])
            if version > SCHEMA_VERSION:
                raise MediaMigrationError(f"future_schema_version:{version}")
            known = _KNOWN_MIGRATIONS.get(version)
            if known is None:
                raise MediaMigrationError(f"unknown_schema_version:{version}")
            expected_name, expected_checksum = known
            if row["name"] != expected_name or row["checksum"] != expected_checksum:
                raise MediaMigrationError(f"migration_checksum_mismatch for version {version}")
            versions.add(version)

        meta_rows = connection.execute(
            "SELECT database_uuid,schema_version FROM database_meta WHERE singleton=1"
        ).fetchall()
        if len(meta_rows) != 1:
            raise MediaMigrationError("database_meta is missing or ambiguous.")
        meta_version = int(meta_rows[0]["schema_version"])
        if meta_version > SCHEMA_VERSION:
            raise MediaMigrationError(f"future_schema_version:{meta_version}")
        if meta_version < 2:
            raise MediaMigrationError(f"unsupported_schema_version:{meta_version}")
        expected_versions = set(range(1, meta_version + 1))
        if versions != expected_versions:
            raise MediaMigrationError("managed_schema_migration_history_incomplete")
        return meta_version

    @staticmethod
    def _normalized_schema_sql(value: object) -> str:
        return " ".join(str(value).split()) if isinstance(value, str) else ""

    @classmethod
    def _rebuild_v9_timeline_command_tables(
        cls,
        connection: sqlite3.Connection,
    ) -> None:
        """Rebuild the two V7 command-envelope tables without rewriting history.

        The caller must own a transaction that began with foreign keys disabled.
        ``legacy_alter_table`` prevents SQLite from redirecting dependent V7/V8
        foreign keys to the temporary names while the canonical names are
        replaced.  Every stored column is copied directly; no JSON is decoded
        and no operation/response/receipt digest is recalculated.
        """

        foreign_keys = int(connection.execute("PRAGMA foreign_keys").fetchone()[0])
        legacy_alter_table = int(connection.execute("PRAGMA legacy_alter_table").fetchone()[0])
        if not connection.in_transaction or foreign_keys != 0 or legacy_alter_table != 1:
            raise MediaMigrationError("v9_rebuild_pragmas_invalid")
        for name in (
            "canonical_timeline_operations_v8",
            "canonical_timeline_receipts_v8",
        ):
            if cls._schema_object_exists(connection, object_type="table", name=name):
                raise MediaMigrationError(f"v9_schema_name_collision:{name}:table")

        for name in (
            "trg_canonical_timeline_receipts_no_update",
            "trg_canonical_timeline_receipts_no_delete",
            "trg_canonical_timeline_operations_no_update",
            "trg_canonical_timeline_operations_no_delete",
        ):
            connection.execute(f"DROP TRIGGER {name}")
        for name in (
            "idx_canonical_timeline_receipts_operation",
            "idx_canonical_timeline_operations_project_sequence",
        ):
            connection.execute(f"DROP INDEX {name}")

        connection.execute("ALTER TABLE canonical_timeline_receipts RENAME TO canonical_timeline_receipts_v8")
