    @classmethod
    def _backfill_v5_desktop_receipt_integrity(
        cls,
        connection: sqlite3.Connection,
    ) -> None:
        """Seal trusted v4 desktop receipts while crossing the v4 -> v5 boundary."""

        broken = connection.execute(
            """SELECT 1 FROM creative_blueprint_operations operation
                WHERE (SELECT COUNT(*) FROM blueprint_command_receipts receipt
                        WHERE receipt.project_id=operation.project_id
                          AND receipt.operation_id=operation.id) != 1
               UNION ALL
               SELECT 1 FROM blueprint_command_receipts receipt
                WHERE NOT EXISTS (
                  SELECT 1 FROM creative_blueprint_operations operation
                   WHERE operation.project_id=receipt.project_id
                     AND operation.id=receipt.operation_id)
               LIMIT 1"""
        ).fetchone()
        if broken is not None:
            raise MediaMigrationError("v4_desktop_receipt_ledger_incomplete")
        try:
            meta = connection.execute(
                "SELECT database_uuid,schema_version FROM database_meta WHERE singleton=1"
            ).fetchone()
            if meta is None or meta["schema_version"] != 4 or not cls._is_blueprint_identifier(meta["database_uuid"]):
                raise BlueprintIntegrityError("v4_database_identity_invalid")
            database_uuid = str(meta["database_uuid"])
            project_ids = connection.execute(
                """SELECT project_id FROM creative_blueprint_heads
                   UNION SELECT project_id FROM creative_blueprint_operations
                   UNION SELECT project_id FROM blueprint_command_receipts
                   ORDER BY project_id"""
            )
            for project_row in project_ids:
                project_id = str(project_row["project_id"])
                cls.get_blueprint_head_in_transaction(
                    connection,
                    project_id,
                    _validate_receipts=False,
                )
            operation_rows = connection.execute(
                """SELECT operation.* FROM creative_blueprint_operations operation
                     JOIN blueprint_command_receipts receipt
                       ON receipt.project_id=operation.project_id
                      AND receipt.operation_id=operation.id
                    ORDER BY operation.project_id,operation.sequence"""
            )
            for operation_row in operation_rows:
                operation = cls._blueprint_operation_from_row(operation_row)
                project_id = str(operation["project_id"])
                row = cls._validate_blueprint_desktop_receipt_record(
                    connection,
                    project_id=project_id,
                    operation=operation,
                    database_uuid=database_uuid,
                    require_sidecar=False,
                )
                material = cls._blueprint_desktop_receipt_material(
                    database_uuid=row["database_uuid"],
                    authenticated_principal=row["authenticated_principal"],
                    project_id=row["project_id"],
                    command_type=row["command_type"],
                    command_version=row["command_version"],
                    idempotency_key=row["idempotency_key"],
                    request_sha256=row["request_sha256"],
                    operation_id=row["operation_id"],
                    response_status=row["response_status"],
                    response_sha256=row["response_sha256"],
                    resource_type=row["resource_type"],
                    resource_id=row["resource_id"],
                    created_at=row["created_at"],
                )
                connection.execute(
                    """INSERT INTO blueprint_desktop_receipt_integrity(
                         project_id,operation_id,receipt_sha256) VALUES(?,?,?)""",
                    (
                        row["project_id"],
                        row["operation_id"],
                        content_sha256(material),
                    ),
                )
        except BlueprintIntegrityError as exc:
            raise MediaMigrationError("v4_desktop_receipt_integrity_invalid") from exc

    @classmethod
    def _validate_all_desktop_receipt_integrity(
        cls,
        connection: sqlite3.Connection,
    ) -> None:
        mismatch = connection.execute(
            """SELECT 1 FROM blueprint_command_receipts receipt
                WHERE (SELECT COUNT(*) FROM blueprint_desktop_receipt_integrity integrity
                        WHERE integrity.project_id=receipt.project_id
                          AND integrity.operation_id=receipt.operation_id) != 1
               UNION ALL
               SELECT 1 FROM blueprint_desktop_receipt_integrity integrity
                WHERE NOT EXISTS (
                  SELECT 1 FROM blueprint_command_receipts receipt
                   WHERE receipt.project_id=integrity.project_id
                     AND receipt.operation_id=integrity.operation_id)
               LIMIT 1"""
        ).fetchone()
        if mismatch is not None:
            raise MediaMigrationError("v5_desktop_receipt_integrity_incomplete")
        rows = connection.execute(
            """SELECT database_uuid,authenticated_principal,project_id,command_type,
                      command_version,idempotency_key,request_sha256,operation_id,
                      response_status,response_sha256,resource_type,resource_id,created_at
                 FROM blueprint_command_receipts ORDER BY project_id,operation_id"""
        )
        try:
            for row in rows:
                cls._validate_blueprint_desktop_receipt_integrity(connection, row)
        except BlueprintIntegrityError as exc:
            raise MediaMigrationError("v5_desktop_receipt_integrity_invalid") from exc

