            source_uri = f"{self.db_path.as_uri()}?mode=ro&nofollow=1"
            destination_uri = f"{backup_path.as_uri()}?mode=rw&nofollow=1"
            with closing(sqlite3.connect(source_uri, uri=True)) as source, source:
                source.execute("PRAGMA query_only=ON")
